const BODY_HTML = "\n  <div class=\"page\">\n    <div class=\"topbar\">\n      <div>\n        <h1 class=\"title\" id=\"greetingTitle\">Hey</h1>\n        <p class=\"subtitle\" id=\"homeDate\"></p>\n      </div>\n      <div class=\"profile-menu-wrap\">\n        <button class=\"profile-btn\" id=\"profileBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-label=\"Profile and settings\"></button>\n        <div class=\"profile-menu\" id=\"profileMenu\" role=\"menu\" hidden>\n          <button class=\"profile-menu-item\" type=\"button\" role=\"menuitem\" data-action=\"settings\">Settings</button>\n          <button class=\"profile-menu-item signout\" type=\"button\" role=\"menuitem\" data-action=\"signout\">Sign out</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-grid\">\n        <div class=\"col-left\" id=\"colLeft\">\n          <div class=\"widget-block\" id=\"block-grades\" data-widget=\"grades\">\n            <div class=\"section-head\">\n              <h2>Grades</h2>\n              <span class=\"see-all\" role=\"link\" tabindex=\"0\" data-href=\"/grades\">See gradebook</span>\n            </div>\n            <table class=\"grades\">\n              <thead>\n                <tr>\n                  <th>Course</th>\n                  <th>Grade</th>\n                  <th>Predicted</th>\n                  <th>Updated</th>\n                </tr>\n              </thead>\n              <tbody id=\"gradesBody\"></tbody>\n            </table>\n          </div>\n\n          <div class=\"today-block widget-block\" id=\"block-today\" data-widget=\"today\">\n            <div class=\"today-head\">\n              <div class=\"today-date\" id=\"todayDate\"></div>\n              <span class=\"see-all\" role=\"link\" tabindex=\"0\" data-href=\"/calendar\">See calendar</span>\n            </div>\n            <div id=\"todayList\"></div>\n          </div>\n\n          <div class=\"widget-block\" id=\"block-recent\" data-widget=\"recent\">\n            <div class=\"section-head\">\n              <h2>Recently graded</h2>\n              <span class=\"see-all\" role=\"link\" tabindex=\"0\" data-href=\"/grades\">See gradebook</span>\n            </div>\n            <div id=\"recentList\"></div>\n          </div>\n        </div>\n\n        <div class=\"col-right\" id=\"colRight\">\n          <div class=\"widget-block\" id=\"block-assignments\" data-widget=\"assignments\">\n            <div class=\"section-head\">\n              <h2>Assignments</h2>\n              <span class=\"see-all\" role=\"link\" tabindex=\"0\" data-href=\"/assignments\">See all</span>\n            </div>\n            <div class=\"sum-card\" id=\"sumCard\" role=\"region\" aria-roledescription=\"carousel\" aria-label=\"Summary\"></div>\n            <div class=\"assign-section-label overdue\">Overdue <span class=\"assign-count\" id=\"overdueCount\">0</span></div>\n            <div id=\"overdueList\"></div>\n            <div class=\"assign-section-label\">Upcoming</div>\n            <div id=\"upcomingList\"></div>\n          </div>\n\n          <div class=\"today-block widget-block widget-messages\" id=\"block-updates\" data-widget=\"updates\">\n            <div class=\"today-head\">\n              <div class=\"today-date\">Course updates</div>\n              <span class=\"updates-new\" id=\"updatesNew\" hidden></span>\n            </div>\n            <div id=\"updatesList\"></div>\n          </div>\n\n          <!-- Optional widget — hidden unless added via the editor's\n               Widgets section (off by default). -->\n          <div class=\"today-block widget-block widget-messages\" id=\"block-messages\" data-widget=\"messages\" hidden>\n            <div class=\"today-head\">\n              <div class=\"today-date\">Messages</div>\n              <span class=\"see-all\" role=\"link\" tabindex=\"0\" data-href=\"/messages\">See messages</span>\n            </div>\n            <div id=\"messagesList\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"grade-popup\" id=\"gradePopup\" role=\"tooltip\"></div>\n\n  <button class=\"edit-fab\" id=\"editFab\" type=\"button\" aria-haspopup=\"dialog\" aria-label=\"Customize this page\">\n    <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n      <path d=\"M12 20h9\"/>\n      <path d=\"M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z\"/>\n    </svg>\n  </button>\n\n  <!-- Shown only while dragging widgets around the page (see JS) — takes\n       the pencil's place at the same spot and returns to the editor. -->\n  <button class=\"drag-done-btn\" id=\"dragDoneBtn\" type=\"button\" hidden>Done</button>\n\n  <div class=\"editor-overlay\" id=\"editorOverlay\">\n    <div class=\"editor-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"editorTitle\">\n      <div class=\"editor-head\">\n        <h2 id=\"editorTitle\">Customize Home</h2>\n        <button class=\"editor-close\" id=\"editorClose\" type=\"button\" aria-label=\"Close editor\">&times;</button>\n      </div>\n      <div class=\"editor-body\" id=\"editorBody\">\n        <div class=\"editor-section\">\n          <h3>Courses</h3>\n          <div id=\"editorCourseList\"></div>\n          <div class=\"color-swatch-popup\" id=\"courseColorPopup\" role=\"menu\" aria-label=\"Preset colors\"></div>\n        </div>\n        <div class=\"editor-section\">\n          <h3>Widgets</h3>\n\n          <div class=\"widget-reorder\">\n            <button class=\"widget-reorder-toggle\" id=\"widgetReorderToggle\" type=\"button\">\n              <span>Reorder &amp; resize widgets</span>\n              <svg class=\"chev\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M9 6l6 6-6 6\"/></svg>\n            </button>\n          </div>\n\n          <div class=\"editor-widget-row\">\n            <div class=\"editor-widget-text\">\n              <p class=\"editor-widget-title\">Assignment overview</p>\n              <p class=\"editor-widget-desc\">The sliding card: next test, next assignment and today.</p>\n            </div>\n            <label class=\"toggle\">\n              <input type=\"checkbox\" id=\"widgetSummaryToggle\" aria-label=\"Show Assignment overview on Home\" checked>\n              <span class=\"track\"><span class=\"thumb\"></span></span>\n            </label>\n          </div>\n          <div class=\"editor-widget-row\">\n            <div class=\"editor-widget-text\">\n              <p class=\"editor-widget-title\">Recently graded</p>\n              <p class=\"editor-widget-desc\">Your newest scores, with the points and when they were posted.</p>\n            </div>\n            <label class=\"toggle\">\n              <input type=\"checkbox\" id=\"widgetRecentToggle\" aria-label=\"Show Recently graded widget on Home\" checked>\n              <span class=\"track\"><span class=\"thumb\"></span></span>\n            </label>\n          </div>\n          <div class=\"editor-widget-row\">\n            <div class=\"editor-widget-text\">\n              <p class=\"editor-widget-title\">Course updates</p>\n              <p class=\"editor-widget-desc\">Announcements from your teachers in every course, newest first.</p>\n            </div>\n            <label class=\"toggle\">\n              <input type=\"checkbox\" id=\"widgetUpdatesToggle\" aria-label=\"Show Course updates widget on Home\" checked>\n              <span class=\"track\"><span class=\"thumb\"></span></span>\n            </label>\n          </div>\n          <div class=\"editor-widget-row\">\n            <div class=\"editor-widget-text\">\n              <p class=\"editor-widget-title\">Today's schedule</p>\n              <p class=\"editor-widget-desc\">What's on today, with a link to your calendar.</p>\n            </div>\n            <label class=\"toggle\">\n              <input type=\"checkbox\" id=\"widgetTodayToggle\" aria-label=\"Show Today's schedule widget on Home\" checked>\n              <span class=\"track\"><span class=\"thumb\"></span></span>\n            </label>\n          </div>\n          <div class=\"editor-widget-row\">\n            <div class=\"editor-widget-text\">\n              <p class=\"editor-widget-title\">Messages</p>\n              <p class=\"editor-widget-desc\">A preview of your recent messages. Off by default.</p>\n            </div>\n            <label class=\"toggle\">\n              <input type=\"checkbox\" id=\"widgetMessagesToggle\" aria-label=\"Show Messages widget on Home\">\n              <span class=\"track\"><span class=\"thumb\"></span></span>\n            </label>\n          </div>\n        </div>\n      </div>\n      <div class=\"editor-actions\">\n        <button class=\"editor-reset\" id=\"editorReset\" type=\"button\">Reset to default</button>\n        <button class=\"editor-done\" id=\"editorDone\" type=\"button\">Done</button>\n      </div>\n    </div>\n  </div>\n\n  <nav class=\"app-nav\" aria-label=\"Main navigation\">\n    <div class=\"app-nav-inner\" id=\"dock\">\n      <button class=\"nav-link active\" type=\"button\" data-page=\"home\">\n        <span class=\"label\">Home</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"courses\" data-href=\"/courses\">\n        <span class=\"label\">Courses</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"grades\" data-href=\"/grades\">\n        <span class=\"label\">Grades</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"assignments\" data-href=\"/assignments\">\n        <span class=\"label\">Assignments</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"files\" data-href=\"/files\">\n        <span class=\"label\">Files</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"calendar\" data-href=\"/calendar\">\n        <span class=\"label\">Calendar</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"messages\" data-href=\"/messages\">\n        <span class=\"label\">Messages</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"contacts\" data-href=\"/contacts\">\n        <span class=\"label\">Contacts</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"settings\" data-href=\"/settings\">\n        <span class=\"label\">Settings</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-more\" type=\"button\" id=\"navMore\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"navMoreMenu\" aria-label=\"More pages\" hidden>\n        <span class=\"label\"><svg viewBox=\"0 0 16 4\" width=\"16\" height=\"4\" aria-hidden=\"true\"><circle cx=\"2\" cy=\"2\" r=\"1.75\"/><circle cx=\"8\" cy=\"2\" r=\"1.75\"/><circle cx=\"14\" cy=\"2\" r=\"1.75\"/></svg></span>\n        <span class=\"dot\"></span>\n      </button>\n    </div>\n    <div class=\"nav-more-menu\" id=\"navMoreMenu\" role=\"menu\" aria-label=\"More pages\" hidden></div>\n  </nav>\n\n  \n\n  \n  \n";
const SCRIPT_JS = "\n    function avgIsId(v) { return /^\\d{1,24}$/.test(String(v == null ? '' : v)); }\n    function avgCourseQ(course) { return (avgIsId(course) ? 'id=' : 'course=') + encodeURIComponent(course == null ? '' : course); }\n    function avgAssignHref(course, title, id, extra) {\n      extra = extra || '';\n      if (avgIsId(id) && avgIsId(course)) return `/assignment?id=${id}${extra}`;\n      return `/assignment?course=${encodeURIComponent(course == null ? '' : course)}&title=${encodeURIComponent(title || '')}${avgIsId(id) ? `&id=${id}` : ''}${extra}`;\n    }\n\n    (function () {\n    var POTATO_CSS = \"body.potato-mode,body.potato-mode *,body.potato-mode *::before,body.potato-mode *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;filter:none!important;text-shadow:none!important}html:has(body.potato-mode){scroll-behavior:auto!important}body.potato-mode,body.potato-mode *{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif!important}body.potato-mode h1.title{font-style:normal!important;transform:none!important}body.potato-mode .trend.has-popup:focus-visible{outline:2px solid currentColor;outline-offset:2px}\";\n    function potatoOn() { return !!(document.body && document.body.classList.contains(\"potato-mode\")); }\n    function applyPotato() {\n      var on = false;\n      try { on = (JSON.parse(localStorage.getItem(\"averages_settings_options\") || \"{}\") || {}).potatoMode === true; } catch (e) {}\n      if (document.body) document.body.classList.toggle(\"potato-mode\", on);\n      if (!document.getElementById(\"potatoStyle\")) {\n        var st = document.createElement(\"style\");\n        st.id = \"potatoStyle\";\n        st.textContent = POTATO_CSS;\n        (document.head || document.documentElement).appendChild(st);\n      }\n      var EP = window.Element && Element.prototype;\n      if (EP && !EP.__potatoPatched) {\n        EP.__potatoPatched = true;\n        var anim = EP.animate;\n        if (anim) EP.animate = function (frames, opts) {\n          if (potatoOn()) opts = (typeof opts === \"number\" || opts == null) ? { duration: 0 } : Object.assign({}, opts, { duration: 0, delay: 0, endDelay: 0, iterations: 1 });\n          return anim.call(this, frames, opts);\n        };\n        var siv = EP.scrollIntoView;\n        if (siv) EP.scrollIntoView = function (arg) {\n          if (potatoOn() && arg && typeof arg === \"object\") arg = Object.assign({}, arg, { behavior: \"auto\" });\n          return siv.call(this, arg);\n        };\n        [\"scrollTo\", \"scrollBy\"].forEach(function (name) {\n          [EP, window].forEach(function (target) {\n            var fn = target[name];\n            if (!fn) return;\n            target[name] = function (a, b) {\n              if (potatoOn() && a && typeof a === \"object\") a = Object.assign({}, a, { behavior: \"auto\" });\n              return b === undefined ? fn.call(this, a) : fn.call(this, a, b);\n            };\n          });\n        });\n      }\n    }\n      applyPotato();\n      window.addEventListener('storage', function (e) { if (e.key === 'averages_settings_options') applyPotato(); });\n    })();\n\n    // Bottom nav \"More\" overflow. Shows as many pages as fit without\n    // cutting a label off (\"Cour...\"); the rest go in the More menu.\n    // The current page always stays in the bar.\n    (function () {\n      const nav = document.querySelector('.app-nav');\n      const inner = nav && nav.querySelector('.app-nav-inner');\n      const more = document.getElementById('navMore');\n      const menu = document.getElementById('navMoreMenu');\n      if (!inner || !more || !menu) return;\n      const links = Array.from(inner.querySelectorAll('.nav-link'));\n\n      const cut = () =>\n        inner.scrollWidth > inner.clientWidth + 1 ||\n        links.some(l => !l.hidden && l.querySelector('.label').scrollWidth > l.querySelector('.label').clientWidth + 1);\n\n      function fit() {\n        closeMenu();\n        links.forEach(l => { l.hidden = false; });\n        more.hidden = true;\n        if (!cut()) return;\n        more.hidden = false;\n        // Hide from the right, but never the current page.\n        for (let i = links.length - 1; i >= 1 && cut(); i--) {\n          if (!links[i].classList.contains('active')) links[i].hidden = true;\n        }\n        const hidden = links.filter(l => l.hidden);\n        more.classList.toggle('has-active', hidden.some(l => l.classList.contains('active')));\n        menu.textContent = '';\n        hidden.forEach(l => {\n          const item = document.createElement('button');\n          item.type = 'button';\n          item.className = 'nav-more-item' + (l.classList.contains('active') ? ' active' : '');\n          item.setAttribute('role', 'menuitem');\n          const text = document.createElement('span'); text.textContent = l.querySelector('.label').textContent; item.appendChild(text);\n          item.addEventListener('click', () => { closeMenu(); l.click(); });\n          menu.appendChild(item);\n        });\n      }\n\n      function openMenu() {\n        const navBox = nav.getBoundingClientRect();\n        const innerBox = inner.getBoundingClientRect();\n        menu.style.right = Math.max(0, navBox.right - innerBox.right) + 'px';\n        menu.hidden = false;\n        nav.classList.add('more-open');\n        more.setAttribute('aria-expanded', 'true');\n        const first = menu.querySelector('.nav-more-item');\n        if (first) first.focus();\n      }\n      function closeMenu() {\n        if (menu.hidden) return;\n        menu.hidden = true;\n        nav.classList.remove('more-open');\n        more.setAttribute('aria-expanded', 'false');\n      }\n\n      more.addEventListener('click', e => {\n        e.stopPropagation();\n        menu.hidden ? openMenu() : closeMenu();\n      });\n      document.addEventListener('click', e => { if (!menu.contains(e.target)) closeMenu(); });\n      document.addEventListener('keydown', e => {\n        if (e.key === 'Escape' && !menu.hidden) { closeMenu(); more.focus(); }\n        if (!menu.hidden && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {\n          const items = Array.from(menu.querySelectorAll('.nav-more-item'));\n          const i = items.indexOf(document.activeElement);\n          const next = items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length];\n          if (next) { e.preventDefault(); next.focus(); }\n        }\n      });\n\n      fit();\n      if (window.ResizeObserver) new ResizeObserver(fit).observe(nav);\n      else window.addEventListener('resize', fit);\n      if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);\n    })();\n  \n\n\n    (function () {\n      function darken(hex, amount) {\n        const n = parseInt(hex.slice(1), 16);\n        const r = Math.max(0, ((n >> 16) & 255) * (1 - amount));\n        const g = Math.max(0, ((n >> 8) & 255) * (1 - amount));\n        const b = Math.max(0, (n & 255) * (1 - amount));\n        return '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');\n      }\n      function applyAppearance() {\n        let saved = null;\n        try {\n          const raw = localStorage.getItem('averages_appearance');\n          if (raw) saved = JSON.parse(raw);\n        } catch {}\n        if (!saved) return;\n        const root = document.documentElement.style;\n        if (saved.accent) {\n          root.setProperty('--accent', saved.accent);\n          root.setProperty('--accent-dark', saved.accentDark || darken(saved.accent, 0.22));\n        }\n        if (saved.background === 'white') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#f4f4f6';\n        } else if (saved.background === 'black') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#0c0c0e';\n        } else if (saved.background) {\n          document.body.style.backgroundImage = `url(\"${saved.background}\")`;\n          document.body.style.backgroundColor = '';\n        }\n      }\n      applyAppearance();\n      window.addEventListener('storage', e => {\n        if (e.key === 'averages_appearance') applyAppearance();\n      });\n    })();\n\n    const AVERAGES_COURSE_CUSTOM_KEY = 'averages_course_custom';\n    const AVERAGES_COURSE_ORDER_KEY = 'averages_course_order';\n    function loadCourseCustom() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_CUSTOM_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return {};\n    }\n    function saveCourseCustom(id, patch) {\n      const all = loadCourseCustom();\n      all[id] = Object.assign({}, all[id], patch);\n      try { localStorage.setItem(AVERAGES_COURSE_CUSTOM_KEY, JSON.stringify(all)); } catch {}\n    }\n    function loadCourseOrder() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_ORDER_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return null;\n    }\n    function saveCourseOrder(ids) {\n      try { localStorage.setItem(AVERAGES_COURSE_ORDER_KEY, JSON.stringify(ids)); } catch {}\n    }\n    function clearCourseCustomizations() {\n      try {\n        localStorage.removeItem(AVERAGES_COURSE_CUSTOM_KEY);\n        localStorage.removeItem(AVERAGES_COURSE_ORDER_KEY);\n      } catch {}\n    }\n    const COURSE_SUBJECTS = [\n      [/\\bchem/, '🧪', '#1b7f67'],\n      [/\\bbio|anatom|physiolog/, '🧬', '#387f33'],\n      [/\\bphysical ed|(^|[^a-z])p\\.?e\\.?($|[^a-z])|fitness|\\bweight/, '🏃', '#c2562b'],\n      [/\\bhealth/, '🩺', '#c0404a'],\n      [/\\bphysics/, '⚛️', '#4a56b8'],\n      [/astronom/, '🔭', '#3b3f8f'],\n      [/environment|\\bearth|geolog/, '🌍', '#2f7f63'],\n      [/robotic/, '🤖', '#55697d'],\n      [/computer|programming|coding|\\bcs[ap]?\\b|software/, '💻', '#2d6f8f'],\n      [/engineer/, '⚙️', '#6a6478'],\n      [/government|civics|politic/, '🏛️', '#2f4f8a'],\n      [/econ/, '📈', '#2e7d4f'],\n      [/psych/, '🧠', '#9a4583'],\n      [/geograph/, '🗺️', '#4c7a5a'],\n      [/histor/, '📜', '#9a5a2a'],\n      [/statistic|\\bstats?\\b/, '📊', '#2f72a8'],\n      [/geometr|\\btrig/, '📐', '#3e64b0'],\n      [/calc|algebra|\\bmath/, '🧮', '#2f5fb3'],\n      [/english|literature|\\blit\\b|writing|composition|language arts|reading/, '📖', '#a63a4f'],\n      [/spanish|french|german|chinese|mandarin|japanese|korean|latin|italian|\\basl\\b|sign language|language/, '🗣️', '#7a4fae'],\n      [/theat|drama/, '🎭', '#a3364b'],\n      [/music|band|choir|orchestra|chorus/, '🎵', '#6b48a8'],\n      [/photo/, '📷', '#4f5d6e'],\n      [/culinary|cooking|\\bfoods?\\b|nutrition/, '🍳', '#b05a26'],\n      [/\\barts?\\b|drawing|painting|ceramic|sculpt|design/, '🎨', '#b03f7a'],\n      [/business|marketing|accounting|financ/, '💼', '#3d5f6e'],\n      [/journalism|yearbook|newspaper/, '📰', '#5c5c6e'],\n      [/science/, '🔬', '#2b7b8c'],\n    ];\n    function courseSubject(name) {\n      const n = String(name || '').toLowerCase();\n      return COURSE_SUBJECTS.find(([re]) => re.test(n)) || null;\n    }\n\n    function applyCourseCustomizationsInPlace(courses) {\n      const custom = loadCourseCustom();\n      // Mutates each course object's own fields in place (never clones,\n      // never reassigns `courses` itself) — this page's editor already\n      // mutates COURSES in place elsewhere (splice, index assignment,\n      // etc.), and keeping RAW_COURSES's binding a plain literal (rather\n      // than wrapping it in a function call) is what lets\n      // scripts/port-pages.mjs's data-overrides transform find and\n      // rewrite it for live Schoology data.\n      courses.forEach(c => {\n        const subject = courseSubject(c.name);\n        if (subject) c.color = subject[2];\n        Object.assign(c, custom[c.id] || {});\n      });\n      const order = loadCourseOrder();\n      if (order && order.length) {\n        const byId = new Map(courses.map(c => [c.id, c]));\n        const ordered = order.filter(id => byId.has(id)).map(id => byId.get(id));\n        // A course not present in the saved order (e.g. added to the demo\n        // data after the order was saved) still shows up, just appended.\n        courses.forEach(c => { if (!order.includes(c.id)) ordered.push(c); });\n        courses.splice(0, courses.length, ...ordered);\n      }\n    }\n    // Raw/default course data, in the mock's original hardcoded order —\n    // COURSES itself (below) starts out as this same array with any saved\n    // customization/order then applied to it in place; DEFAULT_COURSES\n    // (what \"Reset to default\" restores) is captured as a deep clone\n    // BEFORE that happens, never of the customized COURSES, so Reset\n    // always gets back to the true hardcoded defaults even after\n    // renaming, recoloring, or reordering.\n    const RAW_COURSES = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.COURSES) || [\n      { id: 'apchem', name: 'AP Chemistry', color: '#a67a22', grade: 'B+', pct: 87, predicted: 'A-', predictedPct: 91, trend: 'up', updated: '2h ago' },\n      { id: 'algebra2', name: 'Algebra II', color: '#5b6ea3', grade: 'A', pct: 95, predicted: 'A', predictedPct: 95, trend: 'flat', updated: '1d ago' },\n      { id: 'english10', name: 'English 10', color: '#6b8f5e', grade: 'C+', pct: 78, predicted: 'C', predictedPct: 74, trend: 'down', updated: '3h ago' },\n      { id: 'ushistory', name: 'U.S. History', color: '#a15c4f', grade: 'A-', pct: 91, predicted: 'A-', predictedPct: 91, trend: 'flat', updated: '5h ago' },\n      { id: 'spanish3', name: 'Spanish III', color: '#8a6ba1', grade: 'B', pct: 84, predicted: 'B+', predictedPct: 88, trend: 'up', updated: '1d ago' },\n      { id: 'pe', name: 'PE', color: '#4f8c8a', grade: 'A', pct: 97, predicted: 'A', predictedPct: 97, trend: 'flat', updated: '2d ago' },\n    ];\n    const DEFAULT_COURSES = JSON.parse(JSON.stringify(RAW_COURSES));\n    const COURSES = RAW_COURSES;\n    applyCourseCustomizationsInPlace(COURSES);\n    const DEFAULT_WIDGETS = { messages: false, today: true, recent: true, updates: true, summary: true };\n\n    // Per-course assignment score history behind the \"Predicted\" figure —\n    // the real thing (see architecture-decisions.md) extrapolates the\n    // trend across a student's actual assignment averages rather than\n    // copying the current grade; this is the sample trace that popup\n    // visualizes. Last point is the prediction itself, kept separate\n    // from the real (graded) points so the chart can draw it as an\n    // extrapolation rather than a sixth graded assignment. Keyed by\n    // course id (see note above), not by name.\n    //\n    // X-axis is the date each assignment was graded, not the assignment's\n    // own name/title — titles can run long (\"Chapter 6 Discussion Post\")\n    // and don't read well as repeating axis labels the way a short date\n    // does.\n    const HISTORY = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.HISTORY) || {\n      apchem: { points: [72, 79, 84, 88, 90], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'] },\n      algebra2: { points: [94, 96, 93, 97, 95], dates: ['Aug 3', 'Aug 7', 'Aug 11', 'Aug 17', 'Aug 23'] },\n      english10: { points: [88, 82, 79, 76, 73], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'] },\n      ushistory: { points: [89, 93, 88, 92, 90], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'] },\n      spanish3: { points: [76, 80, 83, 85, 87], dates: ['Aug 3', 'Aug 7', 'Aug 11', 'Aug 17', 'Aug 23'] },\n      pe: { points: [96, 98, 95, 97, 96], dates: ['Aug 2', 'Aug 6', 'Aug 10', 'Aug 16', 'Aug 22'] },\n    };\n\n    const TYPE_LABEL = { assignment: 'Assignment', discussion: 'Discussion', assessment: 'Quiz' };\n\n    const OVERDUE = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.OVERDUE) || [\n      { type: 'assignment', title: 'Lab Report #4', courseId: 'apchem', due: 'Fri Aug 21' },\n      { type: 'discussion', title: 'Chapter 6 Discussion', courseId: 'english10', due: 'Thu Aug 20' },\n      { type: 'discussion', title: 'Reading Response', courseId: 'ushistory', due: 'Wed Aug 19' },\n    ];\n\n    // Longest-overdue first (furthest in the past), most-recently-due\n    // last, right above Upcoming — \"due\" strings have no year, so this\n    // assumes the same mock year the topbar's \"Monday, August 24\" date\n    // already implies.\n    function parseMockDate(due) {\n      const MONTHS = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };\n      const parts = due.trim().split(/\\s+/);\n      return new Date(2026, MONTHS[parts[parts.length - 2]], parseInt(parts[parts.length - 1], 10));\n    }\n    OVERDUE.sort((a, b) => parseMockDate(a.due) - parseMockDate(b.due));\n\n    const UPCOMING = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.UPCOMING) || [\n      { type: 'assessment', title: 'Unit 2 Quiz', courseId: 'algebra2', due: 'Mon Aug 24' },\n      { type: 'assignment', title: 'Vocab Worksheet', courseId: 'spanish3', due: 'Tue Aug 25' },\n      { type: 'assignment', title: 'Problem Set 7', courseId: 'algebra2', due: 'Wed Aug 26' },\n      { type: 'assessment', title: 'Gas Laws Test', courseId: 'apchem', due: 'Fri Aug 28' },\n      { type: 'assessment', title: 'Chapter 7 Vocab Quiz', courseId: 'spanish3', due: 'Mon Aug 31' },\n    ];\n\n    const HOME_LIVE = !!(window.__AVERAGES__ && window.__AVERAGES__.data) && window.__AVERAGES__.mode !== 'demo';\n    const HOME_DATA = HOME_LIVE ? window.__AVERAGES__.data : {};\n    const HOME_CLASSROOM = HOME_LIVE && (HOME_DATA.platform === 'classroom' || HOME_DATA.PEOPLE_PLATFORM === 'classroom');\n    let UPDATES_FAILED = HOME_LIVE && !Array.isArray(HOME_DATA.COURSE_UPDATES);\n    function avWall(x) { return window.averagesWallClock ? window.averagesWallClock(x) : (x == null ? new Date() : new Date(x)); }\n    if (HOME_LIVE) {\n      const now = avWall();\n      document.getElementById('homeDate').textContent = now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });\n      document.getElementById('todayDate').textContent = now.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });\n    } else {\n      document.getElementById('homeDate').textContent = 'Monday, August 24';\n      document.getElementById('todayDate').textContent = 'Mon, Aug 24';\n    }\n    // \"Now\" for due math: real time when signed in; the demo's own Monday, Aug 24.\n    const REF_NOW = HOME_LIVE ? avWall() : new Date(2026, 7, 24, 8, 0);\n    const RECENT_GRADES = HOME_LIVE ? (Array.isArray(HOME_DATA.RECENT_GRADES) ? HOME_DATA.RECENT_GRADES : []) : [\n      { title: 'Molarity Practice Set', courseId: 'apchem', when: '2h ago', letter: 'A-', pct: 90, pts: '18/20', isNew: true },\n      { title: 'Essay 2: Rhetorical Analysis', courseId: 'english10', when: '3h ago', letter: 'D+', pct: 68, pts: '27/40', isNew: true },\n      { title: 'Unit 1 Test', courseId: 'algebra2', when: '1d ago', letter: 'A', pct: 94, pts: '47/50' },\n      { title: 'Reading Log 3', courseId: 'english10', when: '1d ago', letter: 'A-', pct: 90, pts: '9/10' },\n    ];\n    let COURSE_UPDATES = HOME_LIVE ? (Array.isArray(HOME_DATA.COURSE_UPDATES) ? HOME_DATA.COURSE_UPDATES : []) : [\n      { from: 'Mr. Alvarez', courseId: 'apchem', when: '1h ago', unread: true, body: 'Lab report grading rubric is posted in Materials. Read it before Thursday’s lab.' },\n      { from: 'Mr. Cho', courseId: 'english10', when: '4h ago', unread: true, body: 'Essay Draft feedback is in. Check the comments before you revise for the final draft.' },\n      { from: 'Mr. Cho', courseId: 'english10', when: '1d ago', body: 'Reminder: Chapter 6 Discussion post is overdue. Late posts still get partial credit through Friday.' },\n      { from: 'Coach Reyes', courseId: 'pe', when: '2d ago', body: 'Fitness test retakes are Wednesday during 6th period. Bring running shoes.' },\n    ];\n\n    // Overdue work belongs in the Assignments list's own Overdue section,\n    // not mixed into today's schedule — this is just what's on deck today.\n    const TODAY = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.TODAY) || [\n      { title: 'Unit 2 Quiz', courseId: 'algebra2' },\n    ];\n\n    // Sample data for the optional Messages widget (see the editor's\n    // Widgets section) — same shape a Schoology /v1/messages listing\n    // would give, trimmed to what a compact preview needs.\n    const MESSAGES = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.MESSAGES) || [\n      { from: 'Mr. Alvarez', courseId: 'apchem', preview: 'Lab report grading rubric is posted — see the Materials tab.', time: '1h ago' },\n      { from: 'Mr. Cho', courseId: 'english10', preview: 'Reminder: Chapter 6 discussion post is due Thursday.', time: '3h ago' },\n      { from: 'Coach Reyes', courseId: 'pe', preview: 'Great work on the fitness test this week!', time: '1d ago' },\n    ];\n\n    /**\n     * Escapes a value for interpolation into an HTML string — safe in both\n     * text positions and quoted attribute values.\n     *\n     * Every `${...}` below that carries course, assignment or message data\n     * MUST go through this. In the live app those strings are not ours:\n     * course names and assignment titles are written by teachers, and message\n     * senders and previews by anyone who can message this student. Rendered\n     * raw into innerHTML they execute as markup in app.averages.io's own\n     * origin, where the session cookie is attached to every API call — i.e. a\n     * classmate could read the student's whole Schoology account by naming\n     * something `<img src=x onerror=...>`. Verified by verify/xss-test.mjs.\n     *\n     * Coerces rather than assuming a string: scores and percentages arrive as\n     * numbers, and nothing shape-checks the bundle on the way in. String(v)\n     * specifically (not `v ?? ''`) so a missing field still renders exactly\n     * what a bare template literal rendered before — escaping is the only\n     * behavior change here.\n     *\n     * NOTE: do not wrap values that are themselves HTML — the chart fragments\n     * (`${gridlines}`, `${xLabels}`, `${buildGradeChartSVG(course)}`) are\n     * markup on purpose and escaping them would print visible tags.\n     */\n    function escapeHtml(value) {\n      return String(value).replace(/[&<>\"']/g, ch => (\n        { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch]\n      ));\n    }\n\n    function findCourse(id) {\n      return COURSES.find(c => c.id === id);\n    }\n\n    function courseColor(id) {\n      const c = findCourse(id);\n      return c ? c.color : 'var(--text-faint)';\n    }\n\n    function courseName(id) {\n      const c = findCourse(id);\n      return c ? c.name : '';\n    }\n\n    function gradeBand(letter) {\n      if (letter.startsWith('A')) return 'good';\n      if (letter.startsWith('B')) return 'mid';\n      if (letter.startsWith('C')) return 'mid';\n      return 'bad';\n    }\n\n    // Diagonal, matching the direction of travel (up-right / down-right)\n    // instead of straight vertical arrows.\n    const TREND_ARROW = { up: '↗', down: '↘', flat: '–' };\n\n    const gradesBody = document.getElementById('gradesBody');\n    function renderGradesTable() {\n      gradesBody.innerHTML = '';\n      COURSES.forEach(c => {\n        const tr = document.createElement('tr');\n        // Row opens the course's own Hub page (/course-home), same\n        // destination and role=\"link\"/data-href convention /courses\n        // already uses for its own rows — see the delegated click/keydown\n        // handlers below, which skip the Predicted-popup trigger the same\n        // way /courses's courseRowNavTarget() does.\n        tr.setAttribute('role', 'link');\n        tr.tabIndex = 0;\n        tr.dataset.href = `/course-home?${avgCourseQ(c.id)}`;\n        tr.setAttribute('aria-label', `Open ${c.name}`);\n        tr.innerHTML = `\n          <td>\n            <div class=\"course-cell\">\n              <span class=\"course-dot\" style=\"background:${escapeHtml(c.color)}\"></span>\n              <span class=\"course-name\">${escapeHtml(c.name)}</span>\n            </div>\n          </td>\n          <td><span class=\"grade-val ${gradeBand(c.grade)}\"><span data-live=\"${escapeHtml(c.id)}:grade\">${escapeHtml(c.grade)}</span>${c.grade === '—' ? '' : `<span class=\"grade-pct\" data-live=\"${escapeHtml(c.id)}:pct\">${escapeHtml(c.pct)}%</span>`}</span></td>\n          <td><span class=\"trend has-popup ${escapeHtml(c.trend)}\" tabindex=\"0\" role=\"button\" aria-haspopup=\"true\" aria-label=\"${c.predicted === '—' ? `${escapeHtml(c.name)} has no grades yet. Show more.` : `Why is ${escapeHtml(c.name)} predicted ${escapeHtml(c.predicted)}, ${escapeHtml(c.predictedPct)} percent? Show reasoning.`}\" data-course=\"${escapeHtml(c.id)}\"><span class=\"arrow\">${TREND_ARROW[c.trend]}</span><span data-live=\"${escapeHtml(c.id)}:predicted\">${escapeHtml(c.predicted)}</span>${c.predicted === '—' ? '' : `<span class=\"grade-pct\" data-live=\"${escapeHtml(c.id)}:predictedPct\">(${escapeHtml(c.predictedPct)}%)</span>`}</span></td>\n          <td class=\"updated\">${escapeHtml(c.updated)}</td>\n        `;\n        gradesBody.appendChild(tr);\n      });\n      bindGradePopupTriggers();\n    }\n    // Delegated so re-renders (widget reorder, editor Done, etc.) don't\n    // need to re-wire anything. Ignores clicks on the Predicted-popup\n    // trigger itself so that keeps its own hover/focus behavior instead\n    // of also navigating away — same split /courses's row handler\n    // already makes between the row and its interactive children.\n    gradesBody.addEventListener('click', e => {\n      if (widgetDragModeOn || e.target.closest('.trend')) return;\n      const row = e.target.closest('tr[data-href]');\n      if (row) window.location.href = row.dataset.href;\n    });\n    gradesBody.addEventListener('keydown', e => {\n      if (e.key !== 'Enter' && e.key !== ' ') return;\n      if (widgetDragModeOn || e.target.closest('.trend')) return;\n      const row = e.target.closest('tr[data-href]');\n      if (!row) return;\n      e.preventDefault();\n      window.location.href = row.dataset.href;\n    });\n\n    // Same course+title query string /assignment already reads for\n    // every other entry point (/assignments's own rows, an\n    // assignment-flagged file in /course-materials) — see\n    // /assignment's findAssignment()/fallback handling, which shows\n    // the real title with generic content even if a Home sample item\n    // doesn't happen to match one of /assignment's own entries.\n    function assignmentHref(item) {\n      return avgAssignHref(item.courseId, item.title, item.id);\n    }\n    function renderAssignList(container, items, overdue) {\n      container.innerHTML = items.map(item => `\n        <div class=\"assign-item ${overdue ? 'is-overdue' : ''}${item.type === 'assessment' ? ' is-test' : ''}\" role=\"link\" tabindex=\"0\" data-href=\"${escapeHtml(assignmentHref(item))}\" aria-label=\"${escapeHtml(item.title)}, ${escapeHtml(courseName(item.courseId))}\">\n          <span class=\"assign-tick\" style=\"background:${escapeHtml(courseColor(item.courseId))}\"></span>\n          <div class=\"assign-text\">\n            <p class=\"assign-title\">${escapeHtml(item.title)}${item.type === 'assessment' ? `<span class=\"test-tag\">${testWord(item)}</span>` : ''}</p>\n            <p class=\"assign-meta\">${item.type === 'assessment' ? '' : `<span class=\"assign-type\">${TYPE_LABEL[item.type] || ''}</span> · `}<span class=\"assign-course\">${escapeHtml(courseName(item.courseId))}</span></p>\n          </div>\n          <span class=\"assign-due\">${escapeHtml(item.due)}</span>\n        </div>\n      `).join('');\n    }\n    const SEEN = window.AveragesSeen || { has: () => false, mark() {}, markMany() {} };\n    function openRow(row) {\n      if (row.dataset.seenKind && row.dataset.seenId) SEEN.mark(row.dataset.seenKind, row.dataset.seenId);\n      window.location.href = row.dataset.href;\n    }\n    function wireRowNav(container) {\n      container.addEventListener('click', e => {\n        if (widgetDragModeOn) return;\n        const row = e.target.closest('[data-href]');\n        if (row) openRow(row);\n      });\n      container.addEventListener('keydown', e => {\n        if (e.key !== 'Enter' && e.key !== ' ') return;\n        if (widgetDragModeOn) return;\n        const row = e.target.closest('[data-href]');\n        if (!row) return;\n        e.preventDefault();\n        openRow(row);\n      });\n    }\n    const OVERDUE_SHOWN = OVERDUE.filter(o => !o.outside);\n    const PENDING_SHOWN = OVERDUE.filter(o => o.outside).map(o => ({ ...o, due: 'Pending' }));\n    function renderAssignLists() {\n      renderAssignList(document.getElementById('overdueList'), OVERDUE_SHOWN, true);\n      renderAssignList(document.getElementById('upcomingList'), PENDING_SHOWN.concat(UPCOMING), false);\n      document.getElementById('overdueCount').textContent = OVERDUE_SHOWN.length;\n    }\n    // Wired once — delegated listeners survive renderAssignList()\n    // replacing the lists' innerHTML on every re-render.\n    wireRowNav(document.getElementById('overdueList'));\n    wireRowNav(document.getElementById('upcomingList'));\n\n    // \"See gradebook\" / \"See calendar\" / \"See all\" / \"See messages\" widget-\n    // header links — same [data-href] convention as everything else, wired\n    // once since these spans never re-render. Scoped to just the header\n    // rows (not the whole card-grid) so it can't intercept clicks meant for\n    // gradesBody's own delegated handler, which has its own .trend-skipping\n    // logic that a broader listener here would bypass.\n    document.querySelectorAll('.section-head .see-all[data-href], .today-head .see-all[data-href]').forEach(el => {\n      el.addEventListener('click', () => { window.location.href = el.dataset.href; });\n      el.addEventListener('keydown', e => {\n        if (e.key !== 'Enter' && e.key !== ' ') return;\n        e.preventDefault();\n        window.location.href = el.dataset.href;\n      });\n    });\n\n    const todayList = document.getElementById('todayList');\n    function renderTodayList() {\n      todayList.innerHTML = TODAY.map(item => `\n        <div class=\"today-item\" role=\"link\" tabindex=\"0\" data-href=\"${escapeHtml(assignmentHref(item))}\" aria-label=\"${escapeHtml(item.title)}, ${escapeHtml(courseName(item.courseId))}\">\n          <span class=\"today-tick\" style=\"background:${escapeHtml(courseColor(item.courseId))}\"></span>\n          <div class=\"today-item-text\">\n            <p class=\"today-item-title\">${escapeHtml(item.title)}</p>\n            <p class=\"today-item-class\">${escapeHtml(courseName(item.courseId))}</p>\n          </div>\n        </div>\n      `).join('');\n    }\n\n    // Widget preview, not a specific thread — Home's sample MESSAGES\n    // entries don't carry the same person/thread id /messages's own\n    // sample data does, so rather than guess at a fragile deep link,\n    // every item opens the inbox itself (same destination the Messages\n    // nav tab already goes to).\n    const messagesList = document.getElementById('messagesList');\n    function renderMessagesWidget() {\n      if (HOME_LIVE && !(Array.isArray(MESSAGES) && MESSAGES.length)) {\n        messagesList.innerHTML = HOME_CLASSROOM\n          ? '<p class=\"widget-empty\">Google Classroom doesn’t have messages.</p>'\n          : '<p class=\"widget-empty\">No messages yet.</p>';\n        return;\n      }\n      messagesList.innerHTML = MESSAGES.map(m => `\n        <div class=\"message-item\" role=\"link\" tabindex=\"0\" data-href=\"/messages\" aria-label=\"Message from ${escapeHtml(m.from)}: ${escapeHtml(m.preview || m.subject || '')}\">\n          <span class=\"message-tick\" style=\"background:${escapeHtml(courseColor(m.courseId))}\"></span>\n          <div class=\"message-item-text\">\n            <div class=\"message-item-top\">\n              <p class=\"message-item-from\">${escapeHtml(m.from)}</p>\n              <p class=\"message-item-time\">${escapeHtml(m.time)}</p>\n            </div>\n            <p class=\"message-item-preview\">${escapeHtml(m.preview || m.subject || '')}</p>\n          </div>\n        </div>\n      `).join('');\n    }\n    wireRowNav(todayList);\n    wireRowNav(messagesList);\n\n    const recentList = document.getElementById('recentList');\n    function renderRecentGrades() {\n      recentList.innerHTML = RECENT_GRADES.length ? RECENT_GRADES.map(r => `\n        <div class=\"rg-item\" role=\"link\" tabindex=\"0\" data-href=\"/gradebook?${avgCourseQ(r.courseId)}\" data-seen-kind=\"g\" data-seen-id=\"${escapeHtml(r.id == null ? '' : r.id)}\" aria-label=\"${escapeHtml([r.title, courseName(r.courseId), [r.letter, typeof r.pct === 'number' ? `${r.pct} percent` : ''].filter(v => v !== undefined && v !== null && v !== '').join(' ')].filter(Boolean).join(', '))}\">\n          <span class=\"assign-tick\" style=\"background:${escapeHtml(courseColor(r.courseId))}\"></span>\n          <div class=\"rg-text\">\n            <p class=\"rg-title\">${escapeHtml(r.title)}${r.isNew && !SEEN.has('g', r.id) ? '<span class=\"new-dot\" title=\"New\"></span>' : ''}</p>\n            <p class=\"rg-meta\">${escapeHtml([courseName(r.courseId), r.when].filter(Boolean).join(' · '))}</p>\n          </div>\n          <div class=\"rg-score\">\n            <span class=\"grade-val ${gradeBand(String(r.letter || ''))}\">${escapeHtml(r.letter || '—')}${typeof r.pct === 'number' && isFinite(r.pct) ? `<span class=\"rg-pct\">${escapeHtml(r.pct)}%</span>` : ''}</span>\n            ${r.pts ? `<span class=\"rg-pts\">${escapeHtml(r.pts)}</span>` : ''}\n          </div>\n        </div>`).join('') : '<p class=\"widget-empty\">No new grades yet.</p>';\n    }\n    const updatesList = document.getElementById('updatesList');\n    function renderCourseUpdates() {\n      const initial = n => String(n).replace(/^(Mr\\.|Mrs\\.|Ms\\.|Mx\\.|Dr\\.|Sra\\.|Sr\\.|Coach)\\s*/i, '').charAt(0).toUpperCase();\n      const poster = u => {\n        const from = String(u.from || '');\n        if (from && from !== 'Announcement') return from;\n        const c = findCourse(u.courseId);\n        const t = c && typeof c.teacher === 'string' ? c.teacher.trim() : '';\n        return t && !t.includes(',') ? t : (from || 'Your teacher');\n      };\n      updatesList.innerHTML = COURSE_UPDATES.length ? COURSE_UPDATES.map(u => ({ ...u, from: poster(u) })).map(u => `\n        <div class=\"tu-item\" role=\"link\" tabindex=\"0\" data-href=\"/course-home?${avgCourseQ(u.courseId)}${u.id != null && u.id !== '' ? `&update=${encodeURIComponent(u.id)}` : ''}#updates\" data-seen-kind=\"u\" data-seen-id=\"${escapeHtml(u.id == null ? '' : u.id)}\" aria-label=\"${escapeHtml(u.from)}, ${escapeHtml(courseName(u.courseId))}: ${escapeHtml(u.body)}\">\n          <span class=\"tu-avatar\" style=\"background:${escapeHtml(window.AveragesAvatar ? window.AveragesAvatar.background(u.from) : courseColor(u.courseId))}\" aria-hidden=\"true\">${escapeHtml(window.AveragesAvatar ? window.AveragesAvatar.initials(u.from) : initial(u.from))}</span>\n          <div class=\"tu-text\">\n            <div class=\"tu-top\">\n              <p><span class=\"tu-from\">${escapeHtml(u.from)}</span>${courseName(u.courseId) ? ` <span class=\"tu-course\">· ${escapeHtml(courseName(u.courseId))}</span>` : ''}</p>\n              <span class=\"tu-time\">${escapeHtml(u.when)}${u.unread && !SEEN.has('u', u.id) ? '<span class=\"new-dot\" title=\"New\"></span>' : ''}</span>\n            </div>\n            <p class=\"tu-body\">${escapeHtml(u.body)}</p>\n          </div>\n        </div>`).join('') : (UPDATES_FAILED ? '<p class=\"widget-empty\">Teacher updates didn’t load this time.</p>' : '<p class=\"widget-empty\">No updates from your teachers yet.</p>');\n      const unread = COURSE_UPDATES.filter(u => u.unread && !SEEN.has('u', u.id)).length;\n      const tag = document.getElementById('updatesNew');\n      tag.hidden = !unread; tag.textContent = `${unread} new`;\n    }\n    wireRowNav(recentList);\n    wireRowNav(updatesList);\n    window.__averagesExtraLanded = function (name) {\n      if (!HOME_LIVE) return;\n      if (name === 'updates') {\n        UPDATES_FAILED = !Array.isArray(HOME_DATA.COURSE_UPDATES);\n        COURSE_UPDATES = UPDATES_FAILED ? [] : HOME_DATA.COURSE_UPDATES;\n      }\n      // people: Classroom posts show the class's teacher, now that it's known.\n      if (name === 'updates' || name === 'people') renderCourseUpdates();\n    };\n\n    const SUMMARY_KEY = 'averages_home_summary';\n    const SUM_DWELL = 8000;\n    const SUM_REDUCE = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;\n    const SUM_CHEV = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 9l6 6 6-6\"/></svg>';\n    const SUM_CHECK = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12l5 5 9-10\"/></svg>';\n    const SHORT_DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];\n    function dayStart(d) { return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }\n    function dueDateOf(item) {\n      if (item.dueAt) { const d = avWall(item.dueAt); if (!isNaN(d)) return d; }\n      try { const d = parseMockDate(String(item.due || '')); return isNaN(d) ? null : d; } catch { return null; }\n    }\n    function daysAway(d) { return Math.round((dayStart(d) - dayStart(REF_NOW)) / 86400000); }\n    function testWord(item) { return /\\b(test|exam|final|midterm)\\b/i.test(item.title) ? 'Test' : 'Quiz'; }\n    function tileFor(d) {\n      const n = daysAway(d);\n      return { top: n === 0 ? 'Today' : n === 1 ? 'Tmrw' : SHORT_DOW[d.getDay()], num: d.getDate() };\n    }\n    function buildSummaryCats() {\n      const dated = UPCOMING.map(i => ({ ...i, _d: dueDateOf(i) })).filter(i => i._d && daysAway(i._d) >= 0).sort((a, b) => a._d - b._d);\n      const tests = dated.filter(i => i.type === 'assessment');\n      const work = dated.filter(i => i.type !== 'assessment');\n      const cats = [];\n      if (tests.length) cats.push({ key: 'test', label: 'Next test', desc: 'Your upcoming quizzes and tests', items: tests.slice(0, 5).map(i => {\n        const n = daysAway(i._d);\n        return { ...tileFor(i._d), color: courseColor(i.courseId), title: i.title, href: assignmentHref(i),\n          meta: `${courseName(i.courseId)} · ${n === 0 ? 'Today' : n === 1 ? 'Tomorrow' : `In ${n} days`}` };\n      }) });\n      if (work.length) cats.push({ key: 'assignment', label: 'Next assignment', desc: 'What you have due next', items: work.slice(0, 5).map(i => {\n        const n = daysAway(i._d);\n        return { ...tileFor(i._d), color: courseColor(i.courseId), title: i.title, href: assignmentHref(i),\n          meta: `${courseName(i.courseId)} · ${n === 0 ? 'Due today' : n === 1 ? 'Due tomorrow' : `Due in ${n} days`}` };\n      }) });\n      const today = dated.filter(i => daysAway(i._d) === 0);\n      const allTests = today.length && today.every(i => i.type === 'assessment');\n      const word = allTests ? (today.length === 1 ? testWord(today[0]).toLowerCase() : (today.every(i => testWord(i) === 'Quiz') ? 'quizzes' : 'tests')) : '';\n      const title = !today.length ? 'Nothing due today' : allTests ? `${today.length} ${word} due today` : `${today.length} thing${today.length === 1 ? '' : 's'} due today`;\n      const metaParts = [];\n      if (today.length) metaParts.push(`${today[0].title}, ${courseName(today[0].courseId)}${today.length > 1 ? ` + ${today.length - 1} more` : ''}`);\n      metaParts.push(OVERDUE_SHOWN.length ? `${OVERDUE_SHOWN.length} overdue` : 'Nothing overdue');\n      cats.push({ key: 'today', label: 'Today', desc: 'A summary of today', items: [\n        { top: SHORT_DOW[REF_NOW.getDay()], num: REF_NOW.getDate(), color: 'var(--accent)', title, meta: metaParts.join(' · '), href: '/calendar' } ] });\n      return cats;\n    }\n    const sumCard = document.getElementById('sumCard');\n    let sumCats = [], sumCat = 0, sumItem = 0, sumTimer = null, sumPaused = false, sumBusy = false;\n    let sumFirst = (() => { try { return localStorage.getItem(SUMMARY_KEY) || 'test'; } catch { return 'test'; } })();\n    sumCard.innerHTML = `<div class=\"sum-view\" aria-live=\"polite\"></div><div class=\"sum-dots\" role=\"group\" aria-label=\"Choose an item\"></div><button class=\"sum-pause\" type=\"button\" aria-label=\"Pause\" title=\"Pause\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path class=\"ps\" d=\"M9 6v12M15 6v12\"/><path class=\"pl\" d=\"M8 5.5v13l11-6.5z\"/></svg></button><div class=\"sum-menu\" role=\"menu\" aria-label=\"Show first\" hidden></div>`;\n    let sumUserPaused = false;   // the pause button: stays paused until pressed again\n    const sumView = sumCard.querySelector('.sum-view'), sumDots = sumCard.querySelector('.sum-dots'), sumMenu = sumCard.querySelector('.sum-menu');\n    function sumSlideEl(c, i) {\n      const C = sumCats[c], it = C.items[i];\n      const el = document.createElement('div');\n      el.className = 'sum-slide'; el.dataset.href = it.href || '';\n      el.innerHTML = `<div class=\"sum-when\" style=\"background:${escapeHtml(it.color)}\"><span>${escapeHtml(it.top)}</span><b>${escapeHtml(it.num)}</b></div>\n        <div class=\"sum-body\"><button class=\"sum-pick\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"${!sumMenu.hidden}\">${escapeHtml(C.label)} ${SUM_CHEV}</button>\n        <p class=\"sum-title\">${escapeHtml(it.title)}</p><p class=\"sum-meta\">${escapeHtml(it.meta)}</p></div>`;\n      return el;\n    }\n    function sumPaintDots() {\n      const items = sumCats[sumCat].items;\n      if (sumDots.dataset.cat !== sumCats[sumCat].key || sumDots.children.length !== (items.length > 1 ? items.length : 0)) {\n        sumDots.dataset.cat = sumCats[sumCat].key;\n        sumDots.innerHTML = items.length > 1 ? items.map((it, k) => `<button class=\"sum-dot\" type=\"button\" data-i=\"${k}\" aria-label=\"${escapeHtml(it.title)}\"></button>`).join('') : '';\n      }\n      sumDots.querySelectorAll('.sum-dot').forEach((d, k) => { d.classList.toggle('on', k === sumItem); d.setAttribute('aria-current', k === sumItem ? 'true' : 'false'); d.style.setProperty('--fill', '0'); });\n    }\n    function sumPaint() { sumView.innerHTML = ''; sumView.appendChild(sumSlideEl(sumCat, sumItem)); sumPaintDots(); }\n    function sumSlideTo(i) {\n      const old = sumView.querySelector('.sum-slide'), back = i < sumItem;\n      sumItem = i; sumPaintDots();\n      if (SUM_REDUCE || !old || document.body.classList.contains('potato-mode')) { sumPaint(); return; }\n      sumBusy = true;\n      const next = sumSlideEl(sumCat, sumItem);\n      sumView.style.height = old.offsetHeight + 'px';\n      sumView.classList.add('sliding');\n      next.classList.add(back ? 'from-left' : 'from-right');\n      sumView.appendChild(next);\n      void next.offsetWidth;\n      old.classList.add(back ? 'to-right' : 'to-left'); next.classList.remove('from-right', 'from-left');\n      setTimeout(() => { old.remove(); sumView.classList.remove('sliding'); sumView.style.height = ''; sumBusy = false; }, 400);\n    }\n    function sumSwitchCat(c) {\n      sumCat = (c + sumCats.length) % sumCats.length; sumItem = 0;\n      if (SUM_REDUCE || sumCats.length === 1 || document.body.classList.contains('potato-mode')) { sumPaint(); return; }\n      sumBusy = true;\n      sumView.classList.add('switching');\n      sumPaintDots();\n      setTimeout(() => { sumPaint(); sumView.classList.remove('switching'); setTimeout(() => { sumBusy = false; }, 270); }, 270);\n    }\n    function sumStep() { if (sumCats[sumCat].items.length > sumItem + 1) sumSlideTo(sumItem + 1); else sumSwitchCat(sumCat + 1); }\n    let sumElapsed = 0, sumLastTs = 0, sumLoopOn = false;\n    function sumFill() {\n      const on = sumDots.querySelector('.sum-dot.on');\n      if (on) on.style.setProperty('--fill', String(Math.min(1, sumElapsed / SUM_DWELL)));\n    }\n    function sumSchedule() {   // (re)start the current card's time from empty\n      sumElapsed = 0;\n      sumFill();\n      if (sumLoopOn) return;\n      sumLoopOn = true;\n      if (document.body.classList.contains('potato-mode')) { sumLoopOn = false; return; }   // Potato mode: no frame loop at all\n      requestAnimationFrame(function loop(ts) {\n        if (document.body.classList.contains('potato-mode')) { sumLoopOn = false; sumLastTs = 0; sumElapsed = 0; sumFill(); return; }\n        const dt = sumLastTs ? Math.min(ts - sumLastTs, 100) : 0;   // no jump after a hidden tab\n        sumLastTs = ts;\n        if (!sumCard.hidden && !sumPaused && !sumUserPaused && sumMenu.hidden && !sumBusy && !widgetDragModeOn && !document.hidden && !document.body.classList.contains('potato-mode')) {   // Potato mode: no auto-advance\n          sumElapsed += dt;\n          if (sumElapsed >= SUM_DWELL) { sumElapsed = 0; sumStep(); }\n        }\n        sumFill();\n        requestAnimationFrame(loop);\n      });\n    }\n    function sumPaintMenu() {\n      sumMenu.innerHTML = '<div class=\"sum-menu-label\">Show first</div>' + sumCats.map(c => `<button class=\"sum-opt${c.key === sumFirst ? ' sel' : ''}\" type=\"button\" role=\"menuitemradio\" aria-checked=\"${c.key === sumFirst}\" data-key=\"${c.key}\"><span>${escapeHtml(c.label)}<small>${escapeHtml(c.desc)}</small></span>${c.key === sumFirst ? SUM_CHECK : ''}</button>`).join('');\n    }\n    function renderSummary() {\n      const curKey = sumCats.length ? sumCats[sumCat].key : sumFirst;\n      sumCats = buildSummaryCats();\n      const at = sumCats.findIndex(c => c.key === curKey);\n      sumCat = at === -1 ? Math.max(0, sumCats.findIndex(c => c.key === sumFirst)) : at;\n      sumItem = Math.min(sumItem, sumCats[sumCat].items.length - 1);\n      sumPaint();\n    }\n    sumCard.addEventListener('mouseenter', () => { sumPaused = true; });\n    sumCard.addEventListener('mouseleave', () => { sumPaused = false; });   // resumes where it paused\n    sumCard.addEventListener('focusin', () => { sumPaused = true; });\n    sumCard.addEventListener('focusout', () => { sumPaused = false; });\n    sumCard.addEventListener('click', e => {\n      if (widgetDragModeOn) return;\n      const pb = e.target.closest('.sum-pause');\n      if (pb) {\n        e.stopPropagation(); sumUserPaused = !sumUserPaused;\n        sumCard.classList.toggle('held', sumUserPaused);\n        pb.setAttribute('aria-label', sumUserPaused ? 'Play' : 'Pause'); pb.title = sumUserPaused ? 'Play' : 'Pause';\n        return;\n      }\n      const dot = e.target.closest('.sum-dot');\n      if (dot) { if (!sumBusy) { const k = Number(dot.dataset.i); if (k !== sumItem) sumSlideTo(k); sumSchedule(); } return; }\n      if (e.target.closest('.sum-pick')) {\n        sumMenu.hidden = !sumMenu.hidden; sumPaintMenu();\n        const b = sumCard.querySelector('.sum-pick'); if (b) b.setAttribute('aria-expanded', String(!sumMenu.hidden));\n        return;\n      }\n      const opt = e.target.closest('.sum-opt');\n      if (opt) {\n        sumFirst = opt.dataset.key; try { localStorage.setItem(SUMMARY_KEY, sumFirst); } catch {}\n        sumMenu.hidden = true;\n        const c = sumCats.findIndex(x => x.key === sumFirst);\n        if (c !== -1 && c !== sumCat) sumSwitchCat(c); else sumPaint();\n        sumSchedule(); return;\n      }\n      if (e.target.closest('.sum-menu')) return;\n      const slide = e.target.closest('.sum-slide[data-href]');\n      if (slide && slide.dataset.href) window.location.href = slide.dataset.href;\n    });\n    document.addEventListener('click', e => { if (!sumMenu.hidden && !sumCard.contains(e.target)) { sumMenu.hidden = true; const b = sumCard.querySelector('.sum-pick'); if (b) b.setAttribute('aria-expanded', 'false'); } });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !sumMenu.hidden) { sumMenu.hidden = true; const b = sumCard.querySelector('.sum-pick'); if (b) { b.setAttribute('aria-expanded', 'false'); b.focus(); } } });\n\n    // Nav: purely visual page-switching for the preview — swaps the\n    // active state, doesn't actually navigate anywhere yet.\n    document.querySelectorAll('.nav-link').forEach(link => {\n      link.addEventListener('click', () => {\n        if (link.dataset.href) { window.location.href = link.dataset.href; return; }\n        document.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));\n        link.classList.add('active');\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Predicted-grade reasoning popup — hover/focus a \"Predicted\" cell\n    // to see the assignment-score trend it's extrapolated from. Single\n    // series per chart (the course's own identity color, already used\n    // for its dot/tick elsewhere), so no legend is needed — the popup\n    // title names it. Y = %, X = the date each recent assignment was\n    // graded plus the predicted point, drawn as a dashed extrapolation\n    // with a hollow marker so it visibly reads as \"not graded yet\"\n    // rather than a sixth real assignment.\n    // ------------------------------------------------------------------\n    function niceBounds(values) {\n      const min = Math.min(...values), max = Math.max(...values);\n      let lo = Math.floor((min - 6) / 10) * 10;\n      let hi = Math.ceil((max + 6) / 10) * 10;\n      lo = Math.max(0, lo);\n      hi = Math.min(100, hi);\n      if (hi - lo < 20) { hi = Math.min(100, lo + 20); }\n      return [lo, hi];\n    }\n\n    function groupSameDay(h) {\n      const days = [];\n      h.points.forEach((p, i) => {\n        const d = h.dates[i];\n        const last = days[days.length - 1];\n        if (last && last.date === d) { last.sum += p; last.n++; }\n        else days.push({ date: d, sum: p, n: 1 });\n      });\n      return Object.assign({}, h, {\n        points: days.map(x => Math.round(x.sum / x.n)),\n        dates: days.map(x => x.n > 1 ? `${x.date} ×${x.n}` : x.date),\n      });\n    }\n    function buildGradeChartSVG(course) {\n      if (!HISTORY[course.id] || !Array.isArray(HISTORY[course.id].points) || !HISTORY[course.id].points.length) return '<p class=\"trend-note\">No graded work yet. The trend shows up after the first grades.</p>';\n      const hist = groupSameDay(HISTORY[course.id]);\n      const allLabels = hist.dates.concat(['Predicted']);\n      const allValues = hist.points.concat([course.predictedPct]);\n      const [yLo, yHi] = niceBounds(allValues);\n\n      const W = 240, H = 108;\n      const padL = 26, padR = 6, padT = 10, padB = 16;\n      const plotW = W - padL - padR, plotH = H - padT - padB;\n\n      const xFor = i => padL + (i / (allLabels.length - 1)) * plotW;\n      const yFor = v => padT + plotH - ((v - yLo) / (yHi - yLo)) * plotH;\n\n      // Gridlines + y labels at low / mid / high of the rounded range.\n      const yTicks = [yLo, Math.round((yLo + yHi) / 2), yHi];\n      const gridlines = yTicks.map(t => `\n        <line x1=\"${padL}\" x2=\"${W - padR}\" y1=\"${yFor(t)}\" y2=\"${yFor(t)}\" stroke=\"var(--border)\" stroke-width=\"1\"/>\n        <text x=\"${padL - 6}\" y=\"${yFor(t) + 3}\" text-anchor=\"end\" font-size=\"8\" fill=\"var(--text-faint)\">${t}%</text>\n      `).join('');\n\n      // Actual (graded) points — solid line, filled dots with a\n      // panel-bg ring so they stay legible crossing the gridlines.\n      const actualPts = hist.points.map((v, i) => [xFor(i), yFor(v)]);\n      const actualLine = actualPts.map(p => p.join(',')).join(' ');\n      const actualMarkers = actualPts.map(([x, y]) => `\n        <circle cx=\"${x}\" cy=\"${y}\" r=\"4\" fill=\"${escapeHtml(course.color)}\" stroke=\"var(--panel-bg)\" stroke-width=\"2\"/>\n      `).join('');\n\n      // Predicted point — dashed extrapolation segment + hollow marker,\n      // so it reads as projected rather than a sixth graded assignment.\n      const predX = xFor(allLabels.length - 1), predY = yFor(course.predictedPct);\n      const lastActual = actualPts[actualPts.length - 1];\n\n      // Shaded band for the projected segment spans the FULL plot height\n      // (top gridline to baseline) — a clean vertical \"this part is\n      // projected\" zone rather than an area-under-curve tied to the\n      // line's own shape. Filled with a diagonal-stripe pattern (not a\n      // flat wash) so it reads as \"not real data yet\" even at a glance\n      // or in grayscale/print, same idea as the dataviz texture channel\n      // — one direction (45°), tone-on-tone in the course's own color.\n      const predictedBand = `x=\"${lastActual[0]}\" y=\"${padT}\" width=\"${predX - lastActual[0]}\" height=\"${plotH}\"`;\n      const stripeDefs = `\n        <pattern id=\"predStripes\" patternUnits=\"userSpaceOnUse\" width=\"6\" height=\"6\" patternTransform=\"rotate(45)\">\n          <rect width=\"6\" height=\"6\" fill=\"${escapeHtml(course.color)}\" fill-opacity=\"0.08\"/>\n          <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"6\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2.2\"/>\n        </pattern>\n      `;\n\n      // X-axis category labels, one per assignment plus \"Predicted\".\n      const xLabels = allLabels.map((lab, i) => `\n        <text x=\"${xFor(i)}\" y=\"${H - 2}\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"var(--text-faint)\">${escapeHtml(lab === 'Predicted' ? 'Pred.' : lab)}</text>\n      `).join('');\n\n      return `\n        <svg viewBox=\"0 0 ${W} ${H}\" width=\"${W}\" height=\"${H}\" role=\"img\" aria-label=\"Line chart of ${escapeHtml(course.name)} assignment scores trending toward a predicted grade of ${escapeHtml(course.predictedPct)} percent\">\n          <defs>${stripeDefs}</defs>\n          ${gridlines}\n          <rect ${predictedBand} fill=\"url(#predStripes)\" stroke=\"none\"/>\n          <polyline points=\"${actualLine}\" fill=\"none\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n          <line x1=\"${lastActual[0]}\" y1=\"${lastActual[1]}\" x2=\"${predX}\" y2=\"${predY}\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-dasharray=\"3 3\"/>\n          ${actualMarkers}\n          <circle cx=\"${predX}\" cy=\"${predY}\" r=\"4.5\" fill=\"var(--panel-bg)\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2\"/>\n          <text x=\"${predX}\" y=\"${predY - 10}\" text-anchor=\"end\" font-size=\"8.5\" font-weight=\"800\" fill=\"var(--text-dark)\">${escapeHtml(course.predictedPct)}%</text>\n          ${xLabels}\n        </svg>\n      `;\n    }\n\n    const TREND_WORD = { up: 'Trending up', down: 'Trending down', flat: 'Holding steady' };\n\n    function renderGradePopup(course) {\n      const hist = HISTORY[course.id];\n      if (!hist || !Array.isArray(hist.points) || !hist.points.length) return `<h3>${escapeHtml(course.name)}</h3><p class=\"popup-sub\">No grades yet. Trend and prediction show after the first grade.</p>`;\n      const first = hist.points[0], lastGraded = hist.points[hist.points.length - 1];\n      return `\n        <h3>${escapeHtml(course.name)}</h3>\n        <p class=\"popup-sub\">${TREND_WORD[course.trend]}: <strong>${escapeHtml(first)}% → ${escapeHtml(lastGraded)}%</strong> over the last ${hist.points.length} graded assignments, predicting <strong>${escapeHtml(course.predictedPct)}%</strong> (${escapeHtml(course.predicted)}).</p>\n        ${buildGradeChartSVG(course)}\n        <p class=\"popup-foot\">Predicted grade extrapolates this trend — not a copy of the current grade.</p>\n      `;\n    }\n\n    const gradePopup = document.getElementById('gradePopup');\n    let popupHideTimer = null;\n\n    function showGradePopup(trigger) {\n      clearTimeout(popupHideTimer);\n      const course = findCourse(trigger.dataset.course);\n      if (!course || !HISTORY[course.id]) return;\n      gradePopup.innerHTML = renderGradePopup(course);\n      gradePopup.classList.add('show');\n      trigger.setAttribute('aria-expanded', 'true');\n\n      // Position above the trigger by default; flip below if that\n      // would go off the top of the viewport. Clamp horizontally so\n      // it never overflows either edge.\n      const rect = trigger.getBoundingClientRect();\n      const popupRect = gradePopup.getBoundingClientRect();\n      let left = rect.left + rect.width / 2 - popupRect.width / 2;\n      left = Math.max(10, Math.min(left, window.innerWidth - popupRect.width - 10));\n      let top = rect.top - popupRect.height - 10;\n      if (top < 10) top = rect.bottom + 10;\n      gradePopup.style.left = `${left}px`;\n      gradePopup.style.top = `${top}px`;\n    }\n\n    function hideGradePopup() {\n      gradePopup.classList.remove('show');\n      document.querySelectorAll('.trend.has-popup[aria-expanded=\"true\"]').forEach(t => t.setAttribute('aria-expanded', 'false'));\n    }\n\n    function bindGradePopupTriggers() {\n      document.querySelectorAll('.trend.has-popup').forEach(trigger => {\n        trigger.addEventListener('mouseenter', () => showGradePopup(trigger));\n        trigger.addEventListener('focus', () => showGradePopup(trigger));\n        trigger.addEventListener('mouseleave', () => { popupHideTimer = setTimeout(hideGradePopup, 80); });\n        trigger.addEventListener('blur', hideGradePopup);\n        trigger.addEventListener('keydown', e => { if (e.key === 'Escape') { hideGradePopup(); trigger.blur(); } });\n      });\n    }\n\n    const WIDGET_PREFS_KEY = 'averages_home_widgets';\n    function loadWidgetPrefs() {\n      try { const v = JSON.parse(localStorage.getItem(WIDGET_PREFS_KEY) || '{}'); return v && typeof v === 'object' ? v : {}; } catch { return {}; }\n    }\n    function saveWidgetPrefs() { try { localStorage.setItem(WIDGET_PREFS_KEY, JSON.stringify(widgetPrefs)); } catch {} }\n    const widgetPrefs = { ...DEFAULT_WIDGETS };\n    { const saved = loadWidgetPrefs(); Object.keys(DEFAULT_WIDGETS).forEach(k => { if (typeof saved[k] === 'boolean') widgetPrefs[k] = saved[k]; }); }\n\n    const editFab = document.getElementById('editFab');\n    const editorOverlay = document.getElementById('editorOverlay');\n    const editorCourseList = document.getElementById('editorCourseList');\n    const widgetMessagesToggle = document.getElementById('widgetMessagesToggle');\n    const messagesWidget = document.getElementById('block-messages');\n    const widgetTodayToggle = document.getElementById('widgetTodayToggle');\n    const todayWidget = document.getElementById('block-today');\n    const widgetRecentToggle = document.getElementById('widgetRecentToggle');\n    const widgetUpdatesToggle = document.getElementById('widgetUpdatesToggle');\n    const widgetSummaryToggle = document.getElementById('widgetSummaryToggle');\n\n    // Drag-and-drop reorder: only mutate the DOM/array on 'drop', never\n    // on 'dragover' (which fires continuously as the mouse moves) — an\n    // element that gets removed/re-rendered out from under an in-progress\n    // native drag ends the drag immediately, so anything live-updating\n    // on dragover would break the gesture it's trying to support.\n    let draggedCourseIdx = null;\n\n    const SWATCH_PALETTE = [\n      ['#e52e2e', '#e58a2e', '#e5e52e', '#8ae52e', '#2ee52e', '#2ee58a', '#2ee5e5', '#2e8ae5', '#2e2ee5', '#8a2ee5', '#e52ee5', '#e52e8a'],\n      ['#f1b1b1', '#f1d1b1', '#f1f1b1', '#d1f1b1', '#b1f1b1', '#b1f1d1', '#b1f1f1', '#b1d1f1', '#b1b1f1', '#d1b1f1', '#f1b1f1', '#f1b1d1'],\n      ['#812222', '#815222', '#818122', '#528122', '#228122', '#228152', '#228181', '#225281', '#222281', '#522281', '#812281', '#812252'],\n      ['#f5f5f5', '#e0e0e0', '#cccccc', '#b8b8b8', '#a3a3a3', '#8f8f8f', '#7a7a7a', '#666666', '#525252', '#3d3d3d', '#292929', '#141414'],\n    ];\n    function initSharedColorSwatchPopup(popup) {\n      let currentBtn = null;\n      let currentOnPick = null;\n      SWATCH_PALETTE.flat().forEach(hex => {\n        const cell = document.createElement('button');\n        cell.type = 'button';\n        cell.className = 'color-swatch-cell';\n        cell.style.background = hex;\n        cell.setAttribute('aria-label', hex);\n        cell.addEventListener('click', () => {\n          if (currentOnPick) currentOnPick(hex);\n          close();\n        });\n        popup.appendChild(cell);\n      });\n      function outsideClick(e) {\n        if (!popup.contains(e.target) && e.target !== currentBtn) close();\n      }\n      function onKeydown(e) {\n        if (e.key === 'Escape') close();\n      }\n      // Anchors under the trigger (right-aligned to it), flips above if\n      // there isn't room below, and clamps left/right/top to the\n      // viewport — same math as the single-trigger version of this\n      // component, plus the same transform-ancestor self-correction (a\n      // no-op here since the editor modal has no transform, but keeps\n      // this copy correct if that ever changes).\n      function reposition() {\n        if (!currentBtn) return;\n        const margin = 10;\n        const b = currentBtn.getBoundingClientRect();\n        const p = popup.getBoundingClientRect();\n        let left = b.right - p.width;\n        left = Math.min(left, window.innerWidth - p.width - margin);\n        left = Math.max(margin, left);\n        let top = b.bottom + 8;\n        if (top + p.height > window.innerHeight - margin) {\n          top = b.top - p.height - 8;\n          if (top < margin) top = margin;\n        }\n        popup.style.left = left + 'px';\n        popup.style.top = top + 'px';\n        const rendered = popup.getBoundingClientRect();\n        const dx = left - rendered.left;\n        const dy = top - rendered.top;\n        if (dx || dy) {\n          popup.style.left = (left + dx) + 'px';\n          popup.style.top = (top + dy) + 'px';\n        }\n      }\n      function open(btn, onPick) {\n        currentBtn = btn;\n        currentOnPick = onPick;\n        popup.classList.add('show');\n        btn.setAttribute('aria-expanded', 'true');\n        reposition();\n        document.addEventListener('click', outsideClick, true);\n        document.addEventListener('keydown', onKeydown);\n        window.addEventListener('scroll', reposition, true);\n        window.addEventListener('resize', reposition);\n      }\n      function close() {\n        if (currentBtn) currentBtn.setAttribute('aria-expanded', 'false');\n        popup.classList.remove('show');\n        currentBtn = null;\n        currentOnPick = null;\n        document.removeEventListener('click', outsideClick, true);\n        document.removeEventListener('keydown', onKeydown);\n        window.removeEventListener('scroll', reposition, true);\n        window.removeEventListener('resize', reposition);\n      }\n      return {\n        toggle(btn, onPick) {\n          if (currentBtn === btn) { close(); return; }\n          open(btn, onPick);\n        },\n        close,\n      };\n    }\n    const courseColorPopup = document.getElementById('courseColorPopup');\n    const sharedSwatchPopup = initSharedColorSwatchPopup(courseColorPopup);\n\n    function setCourseColor(i, hex, wrap) {\n      COURSES[i].color = hex;\n      saveCourseCustom(COURSES[i].id, { color: hex });\n      wrap.querySelector('.editor-course-swatch').style.background = hex;\n      refreshCourseDependentUI();\n    }\n    editorCourseList.addEventListener('click', e => {\n      const trigger = e.target.closest('.editor-course-swatch');\n      if (!trigger) return;\n      e.stopPropagation();\n      const wrap = trigger.closest('.color-swatch-wrap');\n      const i = +wrap.dataset.idx;\n      sharedSwatchPopup.toggle(trigger, hex => setCourseColor(i, hex, wrap));\n    });\n\n    function renderEditorCourseList() {\n      editorCourseList.innerHTML = COURSES.map((c, i) => `\n        <div class=\"editor-course-row\" draggable=\"true\" data-idx=\"${i}\">\n          <span class=\"course-drag-handle\" tabindex=\"0\" role=\"button\" aria-label=\"Drag to reorder ${escapeHtml(c.name)}, or focus and use arrow keys\">\n            <span></span><span></span><span></span><span></span><span></span><span></span>\n          </span>\n          <div class=\"color-swatch-wrap\" data-idx=\"${i}\">\n            <button type=\"button\" class=\"editor-course-swatch\" style=\"background:${escapeHtml(c.color)}\" aria-label=\"Change ${escapeHtml(c.name)} color\" aria-haspopup=\"true\" aria-expanded=\"false\"></button>\n          </div>\n          <input type=\"text\" class=\"editor-course-name\" value=\"${escapeHtml(c.name)}\" data-idx=\"${i}\" aria-label=\"${escapeHtml(c.name)} name\">\n        </div>\n      `).join('');\n\n      editorCourseList.querySelectorAll('.editor-course-name').forEach(input => {\n        input.addEventListener('input', () => {\n          const c = COURSES[+input.dataset.idx];\n          c.name = input.value.trim() || c.name;\n          saveCourseCustom(c.id, { name: c.name });\n          refreshCourseDependentUI();\n        });\n      });\n\n      // Keyboard equivalent to dragging, for anyone who can't drag with\n      // a mouse: focus the handle, then Arrow Up/Down moves that course.\n      editorCourseList.querySelectorAll('.course-drag-handle').forEach(handle => {\n        handle.addEventListener('keydown', e => {\n          const row = handle.closest('.editor-course-row');\n          const i = +row.dataset.idx;\n          let j = null;\n          if (e.key === 'ArrowUp') j = i - 1;\n          else if (e.key === 'ArrowDown') j = i + 1;\n          else return;\n          if (j < 0 || j >= COURSES.length) return;\n          e.preventDefault();\n          [COURSES[i], COURSES[j]] = [COURSES[j], COURSES[i]];\n          saveCourseOrder(COURSES.map(c => c.id));\n          renderEditorCourseList();\n          refreshCourseDependentUI();\n          editorCourseList.querySelectorAll('.course-drag-handle')[j].focus();\n        });\n      });\n    }\n\n    // dragstart is cancelled unless it began on the dot handle, so\n    // grabbing the color swatch or name input never starts a drag.\n    // Some browsers report dragstart's e.target as the draggable ancestor\n    // (the row) rather than the exact element the gesture began on, so\n    // the handle check has to happen on the preceding mousedown instead.\n    let courseDragAllowed = false;\n    editorCourseList.addEventListener('mousedown', e => {\n      courseDragAllowed = !!e.target.closest('.course-drag-handle');\n    });\n    // Live reorder preview: as the dragged row passes over another row,\n    // the rows in between visibly slide out of the way in real time\n    // (via a CSS transform, not a DOM move) instead of only jumping to\n    // their new spot once you let go. Only the dragged row's own DOM\n    // node stays untouched mid-drag — moving/removing it is what\n    // cancels a native drag — everything else here is just cosmetic\n    // transforms cleared again on drop or a cancelled drag.\n    //\n    // Which row the cursor is \"over\" is worked out from raw geometry\n    // (cursor Y vs. each row's original top, measured once at\n    // dragstart) rather than by hit-testing e.target — once other rows\n    // start sliding out of their layout box via transform, the row\n    // that's visually under the cursor is no longer necessarily the\n    // row whose *layout* box the cursor sits in, so element hit-testing\n    // stops lining up with the intended target partway through a drag.\n    let coursePreviewIdx = null;\n    let courseDragRowHeight = 0;\n    let courseListTopAtStart = 0;\n    editorCourseList.addEventListener('dragstart', e => {\n      if (!courseDragAllowed) { e.preventDefault(); return; }\n      const row = e.target.closest('.editor-course-row');\n      draggedCourseIdx = +row.dataset.idx;\n      row.classList.add('dragging');\n      e.dataTransfer.effectAllowed = 'move';\n      const rows = editorCourseList.querySelectorAll('.editor-course-row');\n      courseDragRowHeight = rows.length > 1 ? rows[1].getBoundingClientRect().top - rows[0].getBoundingClientRect().top : 0;\n      courseListTopAtStart = rows[0].getBoundingClientRect().top;\n    });\n    function courseIndexAtY(clientY) {\n      if (!courseDragRowHeight) return draggedCourseIdx;\n      const idx = Math.round((clientY - courseListTopAtStart) / courseDragRowHeight);\n      return Math.max(0, Math.min(COURSES.length - 1, idx));\n    }\n    function previewCourseOrder(targetIdx) {\n      if (targetIdx === coursePreviewIdx) return;\n      coursePreviewIdx = targetIdx;\n      const rh = courseDragRowHeight;\n      editorCourseList.querySelectorAll('.editor-course-row').forEach((row, idx) => {\n        if (idx === draggedCourseIdx) return;\n        let shift = 0;\n        if (draggedCourseIdx < targetIdx && idx > draggedCourseIdx && idx <= targetIdx) shift = -rh;\n        else if (draggedCourseIdx > targetIdx && idx < draggedCourseIdx && idx >= targetIdx) shift = rh;\n        row.style.transition = 'transform 150ms ease';\n        row.style.transform = shift ? `translateY(${shift}px)` : '';\n      });\n    }\n    function clearCoursePreview() {\n      editorCourseList.querySelectorAll('.editor-course-row').forEach(row => {\n        row.style.transition = '';\n        row.style.transform = '';\n      });\n      coursePreviewIdx = null;\n    }\n    editorCourseList.addEventListener('dragover', e => {\n      if (draggedCourseIdx === null) return;\n      e.preventDefault();\n      previewCourseOrder(courseIndexAtY(e.clientY));\n    });\n    editorCourseList.addEventListener('drop', e => {\n      if (draggedCourseIdx === null) return;\n      e.preventDefault();\n      const overIdx = coursePreviewIdx !== null ? coursePreviewIdx : courseIndexAtY(e.clientY);\n      if (overIdx !== draggedCourseIdx) {\n        const [moved] = COURSES.splice(draggedCourseIdx, 1);\n        COURSES.splice(overIdx, 0, moved);\n        saveCourseOrder(COURSES.map(c => c.id));\n        // The preview transforms already slid every row to roughly\n        // where it's about to land, so rebuilding the list here reads\n        // as the tail end of that same motion rather than a snap.\n        renderEditorCourseList();\n        refreshCourseDependentUI();\n      }\n      clearCoursePreview();\n    });\n    editorCourseList.addEventListener('dragend', () => {\n      editorCourseList.querySelectorAll('.editor-course-row.dragging').forEach(r => r.classList.remove('dragging'));\n      draggedCourseIdx = null;\n      clearCoursePreview();\n    });\n\n    // Anything that displays a course's name, color, or order needs to\n    // re-render when any of those change — the table, both assignment\n    // lists, Today, and the Messages widget (color ticks only; senders\n    // aren't tied to a course name). The reasoning popup reads live\n    // from COURSES on next open, so it needs no explicit refresh here.\n    function refreshCourseDependentUI() {\n      renderGradesTable();\n      renderAssignLists();\n      renderTodayList();\n      renderMessagesWidget();\n      renderRecentGrades();\n      renderCourseUpdates();\n      renderSummary();\n    }\n\n    function applyWidgetPrefs() {\n      messagesWidget.hidden = !widgetPrefs.messages;\n      widgetMessagesToggle.checked = widgetPrefs.messages;\n      todayWidget.hidden = !widgetPrefs.today;\n      widgetTodayToggle.checked = widgetPrefs.today;\n      document.getElementById('block-recent').hidden = !widgetPrefs.recent;\n      widgetRecentToggle.checked = widgetPrefs.recent;\n      document.getElementById('block-updates').hidden = !widgetPrefs.updates;\n      widgetUpdatesToggle.checked = widgetPrefs.updates;\n      document.getElementById('sumCard').hidden = !widgetPrefs.summary || document.body.classList.contains('potato-mode');   // the timer below stops while it's hidden\n      widgetSummaryToggle.checked = widgetPrefs.summary;\n    }\n    applyWidgetPrefs();   // a widget turned off last time stays off\n\n    // ------------------------------------------------------------------\n    // Reorder & resize widgets — the editor's button for this closes\n    // the editor and drags the actual widgets on the page instead of an\n    // abstracted list (see enterWidgetDragMode below). Each column\n    // (Grades+Today on the left, Assignments+Messages on the right) is\n    // an ordered list of widget ids; reordering re-appends the column's\n    // children in the new order (appendChild on an already-mounted node\n    // MOVES it, so this never loses state/listeners on the moved\n    // widget — including reparenting it into the OTHER column's list,\n    // which is a real DOM move, not just a reorder). A widget can trade\n    // places with ANY other widget, in either column, not just one in\n    // its own — see onWidgetDragMove/onWidgetDragUp below.\n    // ------------------------------------------------------------------\n    const WIDGET_LABELS = { grades: 'Grades', today: \"Today's schedule\", recent: 'Recently graded', assignments: 'Assignments', updates: 'Course updates', messages: 'Messages' };\n    const BLOCK_EL = {\n      grades: document.getElementById('block-grades'),\n      today: document.getElementById('block-today'),\n      recent: document.getElementById('block-recent'),\n      assignments: document.getElementById('block-assignments'),\n      updates: document.getElementById('block-updates'),\n      messages: document.getElementById('block-messages'),\n    };\n    const ALL_WIDGET_IDS = Object.keys(BLOCK_EL);\n    const colLeftEl = document.getElementById('colLeft');\n    const colRightEl = document.getElementById('colRight');\n\n    let leftOrder = ['grades', 'today', 'recent'];\n    let rightOrder = ['assignments', 'updates', 'messages'];\n    const DEFAULT_LEFT_ORDER = [...leftOrder];\n    const DEFAULT_RIGHT_ORDER = [...rightOrder];\n\n    // Continuous scale (not a 3-tier preset) — driven live by dragging\n    // the corner resize handle, so \"Standard\" as a fixed name doesn't\n    // really apply anymore; 1 is the default/reset size.\n    let widgetSizes = { grades: 1, today: 1, recent: 1, assignments: 1, updates: 1, messages: 1 };\n    const DEFAULT_WIDGET_SIZES = { ...widgetSizes };\n    const RESIZE_MIN = 0.82, RESIZE_MAX = 1.3;\n\n    // Reordering animates into place with a FLIP (First-Last-Invert-\n    // Play): capture where every widget in the column currently is,\n    // reorder the DOM, then transform each one from its old spot back\n    // to 0 and let that transition play — so a swap always visibly\n    // moves rather than snapping, whether it came from a drag-drop or\n    // from Reset to default. If a widget already has a live drag-hover\n    // preview transform applied (see the drop handler below), that\n    // transform is what gets captured as its \"old\" position, so the\n    // hand-off from live preview to this animation is seamless. Tracks\n    // both axes (not just vertical) since a widget can now land in the\n    // OTHER column, which also means a horizontal jump — appendChild\n    // onto a column it wasn't already in reparents it for real, and the\n    // dx term is what bridges that visually instead of it just popping\n    // straight to the new column's X position.\n    function animateReorder(order, colEl) {\n      const first = {};\n      order.forEach(id => { first[id] = BLOCK_EL[id].getBoundingClientRect(); });\n      order.forEach(id => colEl.appendChild(BLOCK_EL[id]));\n      order.forEach(id => {\n        const el = BLOCK_EL[id];\n        el.style.transition = 'none';\n        el.style.transform = '';\n        const last = el.getBoundingClientRect();\n        const dx = first[id].left - last.left;\n        const dy = first[id].top - last.top;\n        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5) {\n          el.style.transform = `translate(${dx}px, ${dy}px)`;\n          requestAnimationFrame(() => {\n            el.style.transition = 'transform 200ms ease';\n            el.style.transform = '';\n          });\n        }\n      });\n    }\n    function applyColumnOrder() {\n      animateReorder(leftOrder, colLeftEl);\n      animateReorder(rightOrder, colRightEl);\n    }\n    function applyWidgetSizes() {\n      Object.keys(widgetSizes).forEach(id => {\n        BLOCK_EL[id].style.zoom = widgetSizes[id];\n        // Keep the resize handle's slider value in sync for screen\n        // readers — role=\"slider\" without a current aria-valuenow only\n        // ever announces the min/max range, never where it actually is.\n        const handle = BLOCK_EL[id].querySelector('.widget-resize-handle');\n        if (handle) handle.setAttribute('aria-valuenow', Math.round(widgetSizes[id] * 100));\n      });\n    }\n\n    // ------------------------------------------------------------------\n    // On-page widget drag mode\n    // ------------------------------------------------------------------\n    let widgetDragModeOn = false;\n    // Single object tracking the widget currently being mouse-dragged\n    // (null when nothing is): { id, rects, startX, startY, targetId,\n    // moved }. See onWidgetDragMove/onWidgetDragUp.\n    let widgetDrag = null;\n    const dragDoneBtn = document.getElementById('dragDoneBtn');\n\n    function resizeHandleHTML(id, corner) {\n      return `<span class=\"widget-resize-handle\" data-corner=\"${corner}\" role=\"slider\" tabindex=\"0\" aria-label=\"Resize ${WIDGET_LABELS[id]}, or focus and use arrow keys\" aria-valuemin=\"${Math.round(RESIZE_MIN * 100)}\" aria-valuemax=\"${Math.round(RESIZE_MAX * 100)}\" aria-valuenow=\"${Math.round(widgetSizes[id] * 100)}\"><span class=\"wrh-ring\"></span><span class=\"wrh-nub\"></span></span>`;\n    }\n\n    let resizing = null; // { id, corner, startX, startY, startScale }\n    function onResizeMove(e) {\n      if (!resizing) return;\n      const dx = e.clientX - resizing.startX;\n      const dy = e.clientY - resizing.startY;\n      // \"Outward\" (growing) is down-right for a bottom-right handle and\n      // down-left for a bottom-left one — project the mouse movement\n      // onto that diagonal so dragging away from the widget grows it\n      // and dragging back toward it shrinks it, from either handle.\n      const outwardX = resizing.corner === 'br' ? dx : -dx;\n      const projected = (outwardX + dy) / 2;\n      const scale = resizing.startScale + projected / 260;\n      widgetSizes[resizing.id] = Math.min(RESIZE_MAX, Math.max(RESIZE_MIN, scale));\n      applyWidgetSizes();\n    }\n    function onResizeUp() {\n      resizing = null;\n      document.removeEventListener('mousemove', onResizeMove);\n      document.removeEventListener('mouseup', onResizeUp);\n    }\n    function attachResizeHandle(id, handle) {\n      handle.addEventListener('mousedown', e => {\n        e.preventDefault();\n        e.stopPropagation();\n        resizing = { id, corner: handle.dataset.corner, startX: e.clientX, startY: e.clientY, startScale: widgetSizes[id] };\n        document.addEventListener('mousemove', onResizeMove);\n        document.addEventListener('mouseup', onResizeUp);\n      });\n      // Keyboard equivalent, same idea as the course drag handle's\n      // Arrow-key reordering: focus the handle, then Arrow keys resize.\n      handle.addEventListener('keydown', e => {\n        let delta = 0;\n        if (e.key === 'ArrowUp' || e.key === 'ArrowRight') delta = 0.04;\n        else if (e.key === 'ArrowDown' || e.key === 'ArrowLeft') delta = -0.04;\n        else return;\n        e.preventDefault();\n        widgetSizes[id] = Math.min(RESIZE_MAX, Math.max(RESIZE_MIN, widgetSizes[id] + delta));\n        applyWidgetSizes();\n      });\n    }\n\n    function widgetColumnOrder(id) {\n      return leftOrder.includes(id) ? leftOrder : rightOrder;\n    }\n\n    // Rect of every VISIBLE widget, center included — hidden ones (the\n    // Messages widget when its toggle is off) are excluded entirely,\n    // since a hidden element's rect collapses to 0×0 at (0,0) and would\n    // otherwise falsely win every \"nearest widget\" comparison near the\n    // top-left of the viewport.\n    function visibleWidgetIds() {\n      return ALL_WIDGET_IDS.filter(id => !BLOCK_EL[id].hidden);\n    }\n    function widgetRect(id) {\n      const r = BLOCK_EL[id].getBoundingClientRect();\n      return { top: r.top, left: r.left, x: r.left + r.width / 2, y: r.top + r.height / 2 };\n    }\n\n    function onWidgetDragMove(e) {\n      if (!widgetDrag) return;\n      const totalDx = e.clientX - widgetDrag.startX;\n      const totalDy = e.clientY - widgetDrag.startY;\n      if (!widgetDrag.moved) {\n        // Small threshold so a plain click (no real movement) doesn't\n        // register as a drag — nothing to preview or commit either way.\n        if (Math.hypot(totalDx, totalDy) < 4) return;\n        widgetDrag.moved = true;\n        BLOCK_EL[widgetDrag.id].style.transition = 'none';\n        BLOCK_EL[widgetDrag.id].classList.add('dragging');\n      }\n      e.preventDefault();\n      const { id, rects } = widgetDrag;\n      BLOCK_EL[id].style.transform = `translate(${totalDx}px, ${totalDy}px)`;\n\n      // Widgets can trade places with ANY other widget now, in either\n      // column, not just one in their own — so instead of \"did you\n      // cross the one other widget in this column,\" the rule is\n      // \"which widget (across the whole card) is your current center\n      // now nearest to.\" Comparing against the dragged widget's OWN\n      // original slot too (not just the others) gives the same\n      // hysteresis the old same-column version had for free: nothing\n      // is targeted, and nothing previews, until you've actually\n      // dragged closer to some other widget than to where you started.\n      const draggedCenter = { x: rects[id].x + totalDx, y: rects[id].y + totalDy };\n      let nearestId = id, nearestDist = Infinity;\n      Object.keys(rects).forEach(wid => {\n        const d = Math.hypot(rects[wid].x - draggedCenter.x, rects[wid].y - draggedCenter.y);\n        if (d < nearestDist) { nearestDist = d; nearestId = wid; }\n      });\n      const newTargetId = nearestId === id ? null : nearestId;\n      if (newTargetId !== widgetDrag.targetId) {\n        if (widgetDrag.targetId) {\n          const prevEl = BLOCK_EL[widgetDrag.targetId];\n          prevEl.style.transition = '';\n          prevEl.style.transform = '';\n        }\n        widgetDrag.targetId = newTargetId;\n        if (newTargetId) {\n          // The target widget previews sliding into the dragged\n          // widget's ORIGINAL slot — a real swap, not a same-column\n          // shuffle, so this can carry it across into the other column\n          // too (see animateReorder's dx handling for the real move).\n          const targetEl = BLOCK_EL[newTargetId];\n          const dx = rects[id].left - rects[newTargetId].left;\n          const dy = rects[id].top - rects[newTargetId].top;\n          targetEl.style.transition = 'transform 150ms ease';\n          targetEl.style.transform = `translate(${dx}px, ${dy}px)`;\n        }\n      }\n    }\n\n    function onWidgetDragUp() {\n      if (!widgetDrag) return;\n      const { id, targetId, moved } = widgetDrag;\n      document.removeEventListener('mousemove', onWidgetDragMove);\n      document.removeEventListener('mouseup', onWidgetDragUp);\n      BLOCK_EL[id].classList.remove('dragging');\n\n      if (moved && targetId) {\n        const sourceOrder = widgetColumnOrder(id);\n        const targetOrder = widgetColumnOrder(targetId);\n        const fromIdx = sourceOrder.indexOf(id);\n        const targetIdx = targetOrder.indexOf(targetId);\n        sourceOrder[fromIdx] = targetId;\n        targetOrder[targetIdx] = id;\n        // If they swapped across columns, each widget's resize handle\n        // (bottom-right in the left column, bottom-left in the right —\n        // see resizeHandleHTML) needs to flip sides to keep facing the\n        // middle of the page in its new column.\n        if (sourceOrder !== targetOrder) {\n          const idHandle = BLOCK_EL[id].querySelector('.widget-resize-handle');\n          const targetHandle = BLOCK_EL[targetId].querySelector('.widget-resize-handle');\n          if (idHandle) idHandle.dataset.corner = leftOrder.includes(id) ? 'br' : 'bl';\n          if (targetHandle) targetHandle.dataset.corner = leftOrder.includes(targetId) ? 'br' : 'bl';\n        }\n      }\n      widgetDrag = null;\n      // FLIP: captures wherever every widget currently sits (including\n      // mid-drag, off-grid pixel offsets, and a widget that's about to\n      // be reparented into the other column) as \"first\", then eases\n      // each into its real slot — a no-op drag (didn't cross the\n      // threshold, or dragged and released with no target) just settles\n      // straight back with no visible jump either way.\n      applyColumnOrder();\n    }\n\n    function startWidgetDrag(id, e) {\n      const rects = {};\n      visibleWidgetIds().forEach(wid => { rects[wid] = widgetRect(wid); });\n      widgetDrag = {\n        id, rects,\n        startX: e.clientX, startY: e.clientY,\n        targetId: null,\n        moved: false,\n      };\n      document.addEventListener('mousemove', onWidgetDragMove);\n      document.addEventListener('mouseup', onWidgetDragUp);\n    }\n\n    // Mouse-based dragging (see the note above .widget-block.drag-mode.\n    // dragging in <style> for why this replaced native HTML5 drag-and-\n    // drop) — initiated by grabbing anywhere on a widget except the\n    // resize handle, whose own mousedown handler already stops this one\n    // via stopPropagation (the closest() check here is defense-in-\n    // depth). Attached ONCE at setup rather than inside\n    // enterWidgetDragMode, which used to re-add a fresh listener on\n    // every entry into drag mode — each one gated by the runtime\n    // `widgetDragModeOn` flag instead — since Reorder & resize widgets\n    // can be opened and closed repeatedly in one session and re-adding\n    // listeners every time would stack duplicates, firing\n    // startWidgetDrag (and its own document-level mousemove/mouseup\n    // listeners) more than once per drag after a couple of cycles.\n    Object.keys(BLOCK_EL).forEach(id => {\n      BLOCK_EL[id].addEventListener('mousedown', e => {\n        if (!widgetDragModeOn) return;\n        if (e.target.closest('.widget-resize-handle')) return;\n        if (e.button !== 0) return;\n        e.preventDefault();\n        startWidgetDrag(id, e);\n      });\n    });\n\n    function enterWidgetDragMode() {\n      widgetDragModeOn = true;\n      closeEditor();\n      Object.keys(BLOCK_EL).forEach(id => {\n        const el = BLOCK_EL[id];\n        el.classList.add('drag-mode');\n        const corner = leftOrder.includes(id) ? 'br' : 'bl';\n        el.insertAdjacentHTML('beforeend', resizeHandleHTML(id, corner));\n        attachResizeHandle(id, el.querySelector('.widget-resize-handle'));\n      });\n      editFab.hidden = true;\n      dragDoneBtn.hidden = false;\n    }\n\n    function exitWidgetDragMode() {\n      widgetDragModeOn = false;\n      widgetDrag = null;\n      document.removeEventListener('mousemove', onWidgetDragMove);\n      document.removeEventListener('mouseup', onWidgetDragUp);\n      Object.keys(BLOCK_EL).forEach(id => {\n        const el = BLOCK_EL[id];\n        el.classList.remove('drag-mode', 'dragging');\n        el.style.transform = '';\n        el.style.transition = '';\n        const handle = el.querySelector('.widget-resize-handle');\n        if (handle) handle.remove();\n      });\n      editFab.hidden = false;\n      dragDoneBtn.hidden = true;\n      openEditor();\n    }\n\n    document.getElementById('widgetReorderToggle').addEventListener('click', enterWidgetDragMode);\n    dragDoneBtn.addEventListener('click', exitWidgetDragMode);\n\n    function openEditor() {\n      renderEditorCourseList();\n      editorOverlay.classList.add('show');\n    }\n    function closeEditor() {\n      editorOverlay.classList.remove('show');\n    }\n\n    editFab.addEventListener('click', openEditor);\n    document.getElementById('editorClose').addEventListener('click', closeEditor);\n    document.getElementById('editorDone').addEventListener('click', closeEditor);\n    editorOverlay.addEventListener('click', e => { if (e.target === editorOverlay) closeEditor(); });\n    document.addEventListener('keydown', e => {\n      if (e.key === 'Escape' && editorOverlay.classList.contains('show')) closeEditor();\n    });\n\n    widgetMessagesToggle.addEventListener('change', () => {\n      widgetPrefs.messages = widgetMessagesToggle.checked;\n      applyWidgetPrefs();\n      saveWidgetPrefs();\n    });\n    widgetTodayToggle.addEventListener('change', () => {\n      widgetPrefs.today = widgetTodayToggle.checked;\n      applyWidgetPrefs();\n      saveWidgetPrefs();\n    });\n    [[widgetRecentToggle, 'recent'], [widgetUpdatesToggle, 'updates'], [widgetSummaryToggle, 'summary']].forEach(([t, k]) => t.addEventListener('change', () => {\n      widgetPrefs[k] = t.checked;\n      applyWidgetPrefs();\n      saveWidgetPrefs();\n    }));\n\n    document.getElementById('editorReset').addEventListener('click', () => {\n      // Restore both the array's CONTENTS and its ORDER to the true\n      // hardcoded defaults — a plain per-index Object.assign (the old\n      // behavior) only overwrote each slot's fields, so a course that\n      // had been reordered kept its new position but got a different\n      // course's id/name/color pasted into it. Clearing and repopulating\n      // in DEFAULT_COURSES's own order (rather than reassigning COURSES\n      // itself) keeps every other closure's reference to this same array\n      // valid, matching how the rest of the editor mutates COURSES in\n      // place. Also clears the persisted customization/order so a future\n      // reload doesn't bring the just-reset state right back.\n      COURSES.length = 0;\n      DEFAULT_COURSES.forEach(c => COURSES.push(JSON.parse(JSON.stringify(c))));\n      clearCourseCustomizations();\n      Object.assign(widgetPrefs, DEFAULT_WIDGETS);\n      try { localStorage.removeItem(WIDGET_PREFS_KEY); } catch {}\n      leftOrder = [...DEFAULT_LEFT_ORDER];\n      rightOrder = [...DEFAULT_RIGHT_ORDER];\n      widgetSizes = { ...DEFAULT_WIDGET_SIZES };\n      refreshCourseDependentUI();\n      applyWidgetPrefs();\n      applyColumnOrder();\n      applyWidgetSizes();\n      renderEditorCourseList();\n    });\n\n    // ------------------------------------------------------------------\n    // Profile menu — Settings / Sign out. Front-end only, same as the\n    // bottom nav: no real page exists to navigate to yet, so this just\n    // opens/closes the menu rather than performing either action.\n    // ------------------------------------------------------------------\n    const profileBtn = document.getElementById('profileBtn');\n    (function () {\n      var profile = null;\n      try {\n        var raw = localStorage.getItem('averages_profile');\n        if (raw) profile = JSON.parse(raw);\n      } catch (e) {}\n      if (!profile || !profile.name || !String(profile.name).trim()) profile = Object.assign({}, profile, { name: window.__AVERAGES_NAME__ || '' });\n      if (profile.photo) {\n        profileBtn.style.backgroundImage = 'url(\"' + profile.photo + '\")';\n        profileBtn.style.backgroundSize = 'cover';\n        profileBtn.style.backgroundPosition = 'center';\n        profileBtn.textContent = '';\n        profileBtn.classList.add('has-photo');\n      } else if (profile.name) {\n        if (window.AveragesAvatar) window.AveragesAvatar.paint(profileBtn, profile.name);\n        else profileBtn.textContent = (function (n) { var p = String(n).trim().split(/\\s+/).filter(Boolean); var f = function (w) { return w ? Array.from(w)[0] : ''; }; return (f(p[0]) + (p.length > 1 ? f(p[p.length - 1]) : '')).toUpperCase(); })(profile.name);\n      }\n      if (profile.name && profile.name.trim()) {\n        var firstName = profile.name.trim().split(/\\s+/)[0];\n        var greetingTitle = document.getElementById('greetingTitle');\n        if (greetingTitle) greetingTitle.textContent = 'Hey, ' + firstName;\n      }\n    })();\n    const profileMenu = document.getElementById('profileMenu');\n\n    function openProfileMenu() {\n      profileMenu.hidden = false;\n      profileBtn.setAttribute('aria-expanded', 'true');\n    }\n    function closeProfileMenu() {\n      profileMenu.hidden = true;\n      profileBtn.setAttribute('aria-expanded', 'false');\n    }\n    profileBtn.addEventListener('click', () => {\n      if (profileMenu.hidden) openProfileMenu(); else closeProfileMenu();\n    });\n    document.addEventListener('click', e => {\n      if (!profileMenu.hidden && !e.target.closest('.profile-menu-wrap')) closeProfileMenu();\n    });\n    document.addEventListener('keydown', e => {\n      if (e.key === 'Escape' && !profileMenu.hidden) { closeProfileMenu(); profileBtn.focus(); }\n    });\n    profileMenu.querySelectorAll('.profile-menu-item').forEach(item => {\n      item.addEventListener('click', () => {\n        if (item.dataset.action === 'settings') { window.location.href = '/settings'; return; }\n        closeProfileMenu();\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Initial render\n    // ------------------------------------------------------------------\n    renderGradesTable();\n    renderAssignLists();\n    renderTodayList();\n    renderMessagesWidget();\n    renderRecentGrades();\n    renderCourseUpdates();\n    // Opened from the bell (or in another tab): those dots go here too.\n    window.addEventListener('averages:seen', () => { renderRecentGrades(); renderCourseUpdates(); });\n    renderSummary();\n    sumSchedule();\n    applyWidgetPrefs();\n    window.__averagesLiveGrades = function () {\n      renderGradesTable();\n      renderRecentGrades();\n      renderSummary();\n    };\n    applyColumnOrder();\n    applyWidgetSizes();\n  \n\n\n    (function () {\n      const SELF = '/home';\n      const KEY = 'averages_nav_trail';\n      const here = SELF + location.search;\n      const label = (document.title || '').replace(/^Averages\\s*[—-]\\s*/, '') || 'Home';\n      let trail = [];\n      try { trail = JSON.parse(sessionStorage.getItem(KEY) || '[]'); } catch {}\n      if (!Array.isArray(trail)) trail = [];\n      const last = trail[trail.length - 1];\n      if (last && last.href === here) last.label = label;                 // reload\n      else if (trail.length > 1 && trail[trail.length - 2].href === here) { trail.pop(); trail[trail.length - 1].label = label; } // went back\n      else trail.push({ href: here, label });\n      trail = trail.slice(-20);\n      try { sessionStorage.setItem(KEY, JSON.stringify(trail)); } catch {}\n\n      const btn = document.querySelector('.back-link');\n      const prev = trail[trail.length - 2];\n      if (!btn || !prev) return;\n      const fresh = btn.cloneNode(false);          // same button, minus old click handlers\n      fresh.removeAttribute('onclick');\n      const icon = btn.querySelector('svg');\n      if (icon) fresh.appendChild(icon.cloneNode(true));\n      const text = document.createElement('span');\n      text.textContent = 'Back to ' + prev.label;\n      fresh.appendChild(text);\n      fresh.addEventListener('click', () => { window.location.href = prev.href; });\n      btn.replaceWith(fresh);\n    })();\n  ";

const ONBOARD_JS = "try{if(localStorage.getItem('averages_onboarded')!=='1')location.replace('/onboard');}catch(e){}";

export default function Page() {
  return (
    <>
      <script dangerouslySetInnerHTML={{ __html: ONBOARD_JS }} />
    <LegacyPage
      title={TITLE}
      bodyHtml={BODY_HTML}
      scriptJs={SCRIPT_JS}
      hasUploads={false}
      externalScripts={[]}
      pageId={"home"}
    />
    </>
  );
}
